/* Finot Académie — Mathématiques 4e : chapitres reconstruits (cours propre à chaque notion + générateurs paramétriques), année 2026-2027.
   Programme appliqué : mathématiques du cycle 4, BO n°31 du 30 juillet 2020 (programme consolidé), toujours applicable en 4e en 2026-2027 ;
   repères annuels de progression et attendus de fin d'année de 4e (Éduscol). Identifiants des chapitres existants conservés. */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,frac,order,bank,pairs,sort,mix,pickN,shuffle,nf,dec,gcd}=H;
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const REF='Mathématiques cycle 4 — programme du BO n°31 du 30 juillet 2020, applicable en 4e en 2026-2027';
const REP='Éduscol — repères annuels de progression et attendus de fin d’année, mathématiques 4e';
const pw=(b,e)=>`${b}<sup>${e<0?'−'+(-e):e}</sup>`;
const mono=(a,v)=>a===0?'':a===1?v:a===-1?'−'+v:nf(a)+v;
function poly(...terms){let s='';for(const [c,v] of terms){if(!c)continue;const abs=Math.abs(c);const body=v?(abs===1?v:nf(abs)+v):nf(abs);if(!s)s=(c<0?'−':'')+body;else s+=(c<0?' − ':' + ')+body;}return s||'0';}
const lin=(a,b,v='x')=>poly([a,v],[b,'']);
const par=n=>n<0?`(${nf(n)})`:nf(n);
const fr=(n,d)=>{const g=gcd(n,d)||1;n/=g;d/=g;if(d<0){n=-n;d=-d;}return d===1?nf(n):`${n<0?'−':''}${Math.abs(n)}/${d}`;};
const fracR=(q,n,d,o={})=>{const g=gcd(n,d)||1;let a=n/g,b=d/g;if(b<0){a=-a;b=-b;}return b===1?num(q,a,o):frac(q,a,b,o);};
const irr=(dens,maxN)=>{const d=P(dens);let n=R(1,maxN);let k=0;while((gcd(n,d)!==1||n%d===0)&&k++<40)n=R(1,maxN);if(gcd(n,d)!==1)n=1;return [n,d];};
const eqF=(n,d)=>F(n,d)===fr(n,d)?'':` = ${fr(n,d)}`;
const F=(n,d)=>`${n<0?'−':''}${Math.abs(n)}/${d}`;
const deg=x=>x*Math.PI/180;
/* Repère et droites (x et y de −5 à 5), pour lire des images ou des coefficients. */
function graph(lines){const u=20,o=120,X=x=>o+x*u,Y=y=>o-y*u;let g='';for(let i=-5;i<=5;i++){g+=`<line x1="${X(i)}" y1="${Y(-5.5)}" x2="${X(i)}" y2="${Y(5.5)}" stroke="currentColor" stroke-opacity="0.15"/><line x1="${X(-5.5)}" y1="${Y(i)}" x2="${X(5.5)}" y2="${Y(i)}" stroke="currentColor" stroke-opacity="0.15"/>`;}
  g+=`<line x1="${X(-5.5)}" y1="${Y(0)}" x2="${X(5.5)}" y2="${Y(0)}" stroke="currentColor" stroke-width="1.5"/><line x1="${X(0)}" y1="${Y(-5.5)}" x2="${X(0)}" y2="${Y(5.5)}" stroke="currentColor" stroke-width="1.5"/>`;
  for(const i of [-4,-2,2,4]){g+=`<text x="${X(i)}" y="${Y(0)+14}" font-size="10" text-anchor="middle" fill="currentColor">${i<0?'−'+(-i):i}</text><text x="${X(0)-8}" y="${Y(i)+4}" font-size="10" text-anchor="end" fill="currentColor">${i<0?'−'+(-i):i}</text>`;}
  g+=`<text x="${X(0)-6}" y="${Y(0)+14}" font-size="10" text-anchor="end" fill="currentColor">0</text><text x="${X(1)}" y="${Y(0)+14}" font-size="10" text-anchor="middle" fill="currentColor">1</text><text x="${X(0)-8}" y="${Y(1)+4}" font-size="10" text-anchor="end" fill="currentColor">1</text>`;
  for(const [a,b] of lines){const x1=-6,x2=6;g+=`<line x1="${X(x1)}" y1="${Y(a*x1+b)}" x2="${X(x2)}" y2="${Y(a*x2+b)}" stroke="#2563eb" stroke-width="2.5"/>`;}
  return `<svg class="fig pfig" viewBox="0 0 240 240" width="240" height="240" role="img" aria-label="Repère avec une droite" style="overflow:hidden">${g}</svg>`;}
const multiP=(q,x,y)=>({type:'multi',q,labels:['abscisse','ordonnée'],ans:[x,y],expl:`Le point a pour coordonnées <b>(${nf(x)} ; ${nf(y)})</b> : abscisse ${nf(x)}, ordonnée ${nf(y)}.`,hint:'Abscisse sur l’axe horizontal, ordonnée sur l’axe vertical.'});

MQ.add('maths','4',[
/* ======================= 4a ======================= */
{id:'4a',name:'Produits et quotients de relatifs',icon:'➗',domain:'Nombres et calculs',
 refs:[REF,REP+' : « multiplier et diviser des nombres relatifs ; règle des signes »'],
 tip:'Compte les facteurs négatifs : nombre pair → résultat positif ; nombre impair → résultat négatif. Puis calcule comme d’habitude sans les signes.',
 c:C(`En 5e, tu as appris à additionner et soustraire des nombres relatifs. Comment calculer (−4) × 3, ou (−20) ÷ (−5) ? Une seule règle suffit : la <b>règle des signes</b>.`,
  [T('Règle des signes',`<p>Le produit (ou le quotient) de deux nombres <b>de même signe</b> est <b>positif</b> ; de deux nombres <b>de signes contraires</b>, il est <b>négatif</b>.</p><p>(−4) × 3 = −12 ; (−4) × (−3) = 12 ; 20 ÷ (−5) = −4 ; (−20) ÷ (−5) = 4.</p><p>Avec plusieurs facteurs : le produit est positif si le nombre de facteurs négatifs est <b>pair</b>, négatif s’il est <b>impair</b>. (−2) × (−3) × (−5) = −30 (trois facteurs négatifs).</p>`),
   T('Priorités et calculs mixtes',`<p>Les règles de priorité ne changent pas : parenthèses, puis multiplications et divisions, puis additions et soustractions.</p><p>−3 + 4 × (−5) = −3 + (−20) = −23 ; (−3 + 4) × (−5) = 1 × (−5) = −5.</p><p>Un quotient de relatifs peut s’écrire en fraction : −12/4 = −3 et 12/(−4) = −3.</p>`)],
  [{q:'Calculer A = (−2) × 5 − (−18) ÷ 3.',s:['Priorités : d’abord le produit et le quotient.','(−2) × 5 = −10 et (−18) ÷ 3 = −6.','A = −10 − (−6) = −10 + 6 = −4.']}],
  ['Je repère les priorités.','Pour chaque produit ou quotient, je détermine le signe (règle des signes).','Je calcule la valeur sans les signes.','Je termine les additions et soustractions de relatifs.'],
  ['Appliquer la règle des signes à une addition : −3 + (−4) = −7, pas +7.','Oublier un signe moins en recopiant.','Ignorer les priorités : −3 + 4 × (−5) n’est pas (1) × (−5).'],
  ['Même signe → positif ; signes contraires → négatif.','Nombre pair de facteurs négatifs → produit positif.','Les priorités s’appliquent aussi aux relatifs.']),
 g:mix([d=>{const a=R(-12,12)||-3,b=R(-12,12)||4;return num(`Calcule : ${par(a)} × ${par(b)}`,a*b,{expl:`${a<0===b<0?'Même signe : positif':'Signes contraires : négatif'} ; ${Math.abs(a)} × ${Math.abs(b)} = ${Math.abs(a*b)}. Résultat : <b>${nf(a*b)}</b>.`,hint:'Règle des signes.'});},3],
  [d=>{const b=R(-9,9)||-2,q=R(-12,12)||5;const a=b*q;return num(`Calcule : ${par(a)} ÷ ${par(b)}`,q,{expl:`${a<0===b<0?'Même signe : positif':'Signes contraires : négatif'} ; ${Math.abs(a)} ÷ ${Math.abs(b)} = ${Math.abs(q)}. Résultat : <b>${nf(q)}</b>.`,hint:'Même règle des signes que pour le produit.'});},2],
  [d=>{const n=R(3,d===1?3:5);const f=Array.from({length:n},()=>(R(1,5))*P([1,-1]));const p=f.reduce((x,y)=>x*y,1);const neg=f.filter(x=>x<0).length;
   return num(`Calcule : ${f.map(par).join(' × ')}`,p,{expl:`${neg} facteur${neg>1?'s':''} négatif${neg>1?'s':''} : ${neg%2?'nombre impair → résultat négatif':'nombre pair → résultat positif'}. Résultat : <b>${nf(p)}</b>.`,hint:'Compte les facteurs négatifs.'});},2],
  [d=>{const a=R(-9,9),b=R(-6,6)||2,c=R(-6,6)||-3;const v=a+b*c;return num(`Calcule : ${nf(a)} + ${par(b)} × ${par(c)}`,v,{expl:`Priorité au produit : ${par(b)} × ${par(c)} = ${nf(b*c)} ; puis ${nf(a)} + ${par(b*c)} = <b>${nf(v)}</b>.`,hint:'La multiplication est prioritaire.'});},2],
  [bank([['Quel est le signe de (−7) × (−8) × (−1) ?','négatif',['positif','nul','on ne peut pas savoir'],'Trois facteurs négatifs : nombre impair.'],{tf:'(−5)² = −25.',v:false,e:'(−5)² = (−5) × (−5) = 25.'},['Que vaut −12/(−4) ?','3',['−3','8','−8'],'Même signe : positif.'],
   {tf:'Un produit qui contient le facteur 0 vaut 0, quels que soient les signes.',v:true,e:'0 multiplié par n’importe quel nombre donne 0.'}]),1])},

/* ======================= 4b ======================= */
{id:'4b',name:'Fractions : les quatre opérations',icon:'🍰',domain:'Nombres et calculs',
 refs:[REF,REP+' : « additionner, soustraire, multiplier et diviser des fractions (relatives) »'],
 tip:'Addition : même dénominateur d’abord ! Multiplication : numérateur × numérateur, dénominateur × dénominateur. Division : on multiplie par l’inverse.',
 c:C(`Une recette demande 3/4 de litre de lait, mais tu n’en fais que les 2/3 : quelle quantité de lait ? Et combien de verres de 1/8 L peut-on remplir avec 3/2 L ? Pour répondre, il faut maîtriser les <b>quatre opérations sur les fractions</b>.`,
  [T('Addition et soustraction',`<p>On met les fractions au <b>même dénominateur</b>, puis on additionne (ou soustrait) les numérateurs : 2/3 + 1/4 = 8/12 + 3/12 = <b>11/12</b> ; 5/6 − 1/2 = 5/6 − 3/6 = 2/6 = <b>1/3</b>.</p><p>On ne doit jamais additionner les dénominateurs : 1/2 + 1/3 ≠ 2/5.</p>`),
   T('Multiplication et division',`<p><b>a/b × c/d = (a × c)/(b × d)</b> : 2/3 × 3/4 = 6/12 = 1/2. Prendre « les 2/3 de 3/4 », c’est multiplier.</p><p>L’<b>inverse</b> de c/d (non nul) est d/c. Diviser par une fraction, c’est <b>multiplier par son inverse</b> : 3/2 ÷ 1/8 = 3/2 × 8/1 = 24/2 = 12.</p><p>Les règles des signes s’appliquent : −2/5 × 3/4 = −6/20 = −3/10.</p>`)],
  [{q:'Calculer 5/6 − 2/3 × 1/4.',s:['Priorité à la multiplication : 2/3 × 1/4 = 2/12 = 1/6.','5/6 − 1/6 = 4/6.','4/6 = 2/3 (simplification par 2).']}],
  ['Je repère l’opération et les priorités.','Addition/soustraction : même dénominateur.','Multiplication : numérateurs ensemble, dénominateurs ensemble ; division : multiplier par l’inverse.','Je simplifie le résultat.'],
  ['Additionner numérateurs et dénominateurs : 1/2 + 1/3 ≠ 2/5.','Chercher un dénominateur commun pour multiplier : inutile.','Diviser par une fraction sans prendre l’inverse.'],
  ['a/b + c/b = (a + c)/b.','a/b × c/d = (a × c)/(b × d).','Diviser par c/d = multiplier par d/c.']),
 g:mix([d=>{const [a,b]=irr([2,3,4,5,6],8);const [c,dd]=irr([2,3,4,6,8,9,10].filter(x=>x!==b),12);const s=P(d===1?[1]:[1,-1]);
   return fracR(`Calcule et simplifie : ${F(a,b)} ${s>0?'+':'−'} ${F(c,dd)}`,a*dd+s*c*b,b*dd,{expl:`Même dénominateur : ${F(a*dd,b*dd)} ${s>0?'+':'−'} ${F(c*b,b*dd)} = <b>${F(a*dd+s*c*b,b*dd)}${eqF(a*dd+s*c*b,b*dd)}</b>.`,hint:'Réduis au même dénominateur.'});},3],
  [d=>{const [a0,b]=irr([2,3,4,5,7,8,9],9),[c,dd]=irr([2,3,4,5,6,7,9],9);const a=a0*(d===3?P([1,-1]):1);return fracR(`Calcule et simplifie : ${F(a,b)} × ${F(c,dd)}`,a*c,b*dd,{expl:`${F(a,b)} × ${F(c,dd)} = <b>${F(a*c,b*dd)}${eqF(a*c,b*dd)}</b>.`,hint:'Numérateur × numérateur, dénominateur × dénominateur.'});},3],
  [d=>{const [a,b]=irr([2,3,4,5,7,8,9],9),[c,dd]=irr([2,3,4,5,6,7,9],9);return fracR(`Calcule et simplifie : ${F(a,b)} ÷ ${F(c,dd)}`,a*dd,b*c,{expl:`On multiplie par l’inverse : ${F(a,b)} × ${F(dd,c)} = <b>${F(a*dd,b*c)}${eqF(a*dd,b*c)}</b>.`,hint:'Diviser = multiplier par l’inverse.'});},2],
  [d=>{const q=P([[2,3],[3,4],[1,2],[2,5],[3,5],[5,6]]),n=P([60,120,240,90,150,300]);return num(`Une salle de ${n} places est remplie aux ${F(q[0],q[1])}. Combien de places sont occupées ?`,n*q[0]/q[1],{expl:`${F(q[0],q[1])} de ${n} = ${n} × ${q[0]} ÷ ${q[1]} = <b>${n*q[0]/q[1]}</b>.`,hint:'Prendre une fraction d’un nombre, c’est multiplier.'});},1],
  [bank([['Quel est l’inverse de 3/7 ?','7/3',['−3/7','3/7','1/7'],'L’inverse de a/b est b/a.'],{tf:'1/2 + 1/3 = 2/5.',v:false,e:'1/2 + 1/3 = 3/6 + 2/6 = 5/6.'},['Combien de verres de 1/8 L peut-on remplir avec 3/2 L ?','12',['3/16','4','16'],'3/2 ÷ 1/8 = 3/2 × 8 = 12.',2]]),1])},

/* ======================= 4c ======================= */
{id:'4c',name:'Puissances de 10 et notation scientifique',icon:'🔭',domain:'Nombres et calculs',
 refs:[REF,REP+' : « utiliser les puissances de 10 d’exposant positif ou négatif ; notation scientifique ; puissances d’un nombre relatif »'],
 tip:'10ⁿ, c’est 1 suivi de n zéros ; 10⁻ⁿ, c’est 0,00…1 avec le 1 au n-ième rang après la virgule.',
 c:C(`La masse de la Terre vaut environ 6 000 000 000 000 000 000 000 000 kg ! Personne n’écrit ce nombre en entier : on écrit <b>6 × 10<sup>24</sup> kg</b>. Les puissances de 10 rendent ces nombres lisibles et comparables.`,
  [T('Puissances d’un nombre',`<p>a<sup>n</sup> = a × a × … × a (n facteurs) : 3<sup>4</sup> = 81 ; (−2)<sup>3</sup> = −8 ; (−2)<sup>4</sup> = 16.</p><p>10<sup>n</sup> = 1 suivi de n zéros : 10<sup>5</sup> = 100 000. 10<sup>−n</sup> = 1/10<sup>n</sup> : 10<sup>−3</sup> = 0,001. Par convention 10<sup>0</sup> = 1.</p><p>Multiplier par 10<sup>n</sup> décale la virgule de n rangs vers la droite ; multiplier par 10<sup>−n</sup>, de n rangs vers la gauche : 3,7 × 10<sup>−2</sup> = 0,037.</p>`),
   T('Notation scientifique',`<p>Tout nombre décimal positif s’écrit a × 10<sup>n</sup> avec <b>1 ≤ a &lt; 10</b> : 34 500 = 3,45 × 10<sup>4</sup> ; 0,006 2 = 6,2 × 10<sup>−3</sup>.</p><p>Pour comparer deux nombres en notation scientifique, on compare d’abord les exposants : 7 × 10<sup>3</sup> &lt; 1,2 × 10<sup>4</sup>.</p>`)],
  [{q:'Écrire 0,000 45 et 45 000 en notation scientifique.',s:['0,000 45 : la virgule va après le 4, déplacement de 4 rangs vers la droite → 4,5 × 10<sup>−4</sup>.','45 000 : 4,5 × 10 000 = 4,5 × 10<sup>4</sup>.','On contrôle : les deux nombres ont la même mantisse 4,5 mais des exposants opposés.']}],
  ['Je place la virgule après le premier chiffre non nul.','Je compte le décalage de la virgule.','Grand nombre → exposant positif ; petit nombre → exposant négatif.','Je vérifie que a est entre 1 et 10.'],
  ['Confondre 10<sup>3</sup> (1 000) et 10 × 3 (30).','Croire que 10<sup>−2</sup> est négatif : c’est 0,01, un nombre positif.','Écrire 45 × 10<sup>3</sup> en le prenant pour une notation scientifique.'],
  ['10<sup>n</sup> = 1 suivi de n zéros ; 10<sup>−n</sup> = 1/10<sup>n</sup>.','Notation scientifique : a × 10<sup>n</sup>, 1 ≤ a &lt; 10.','(−a)<sup>n</sup> est positif si n est pair, négatif si n est impair.']),
 g:mix([d=>{const n=R(d===1?1:-6,7);return ch(`Quelle est l’écriture décimale de ${pw(10,n)} ?`,n>=0?nf(10**n):'0,'+'0'.repeat(-n-1)+'1',[n>=0?String(10*n||1):'−'+nf(10**(-n)),n>=0?'0,'+'0'.repeat(Math.max(0,n-1))+'1':nf(10**(-n)),n>=0?nf(10**(n+1)):'0,'+'0'.repeat(-n)+'1'],{expl:n>=0?`1 suivi de ${n} zéro${n>1?'s':''} : <b>${nf(10**n)}</b>.`:`${pw(10,n)} = 1/${nf(10**(-n))} = <b>0,${'0'.repeat(-n-1)}1</b>.`,hint:'Compte les zéros ou les rangs après la virgule.'});},2],
  [d=>{const m=R(11,99),e=d===1?R(2,6):P([-6,-5,-4,-3,-2,2,3,4,5,6,7]);const show=e<0?'0,'+'0'.repeat(-e-1)+String(m).replace(/0$/,''):nf(m*10**(e-1));const good=`${nf(m/10)} × ${pw(10,e)}`;
   return ch(`Notation scientifique de <b>${show}</b> ?`,good,[`${m} × ${pw(10,e-1)}`,`${nf(m/10)} × ${pw(10,-e)}`,`${nf(m/10)} × ${pw(10,e+1)}`],{expl:`On place la virgule après le premier chiffre : ${nf(m/10)} ; décalage de ${Math.abs(e)} rang${Math.abs(e)>1?'s':''} : <b>${good}</b>.`,hint:'1 ≤ a &lt; 10.'});},3],
  [d=>{const b=P([2,3,4,5,-2,-3,-1,10]),e=R(2,b===10?6:d===1?3:5);return num(`Calcule ${b<0?'('+nf(b)+')':b}<sup>${e}</sup>.`,b**e,{expl:`${Array(e).fill(par(b)).join(' × ')} = <b>${nf(b**e)}</b>.`,hint:'Écris le produit.'});},2],
  [d=>{const x=R(11,99)/10,e=R(-4,4)||2;return num(`Calcule ${nf(x)} × ${pw(10,e)} (écriture décimale).`,Math.round(x*10**e*1e8)/1e8,{expl:`On décale la virgule de ${Math.abs(e)} rang${Math.abs(e)>1?'s':''} vers la ${e>0?'droite':'gauche'} : <b>${nf(Math.round(x*10**e*1e8)/1e8)}</b>.`,hint:'Exposant positif → vers la droite ; négatif → vers la gauche.'});},2],
  [bank([['Quel nombre est le plus petit ?','8 × 10<sup>−3</sup>',['1 × 10<sup>−2</sup>','9 × 10<sup>−2</sup>','2 × 10<sup>−3</sup> × 10'],'On compare les exposants : 10<sup>−3</sup> &lt; 10<sup>−2</sup> ; 2 × 10<sup>−3</sup> × 10 = 2 × 10<sup>−2</sup>.'],{tf:'10<sup>−2</sup> est un nombre négatif.',v:false,e:'10<sup>−2</sup> = 0,01 &gt; 0.'},['(−1)<sup>2025</sup> vaut…','−1',['1','2025','−2025'],'Exposant impair : le résultat est négatif.',3]]),1])},

/* ======================= 4d ======================= */
{id:'4d',name:'Racine carrée et valeurs approchées',icon:'√',domain:'Nombres et calculs',
 refs:[REF,REP+' : « racine carrée d’un nombre positif (en lien avec le théorème de Pythagore) ; valeur approchée, arrondi »'],
 tip:'Connais par cœur les carrés de 1 à 15 : ils permettent d’encadrer n’importe quelle racine carrée.',
 c:C(`Avec le théorème de Pythagore, on trouve souvent une longueur dont on connaît seulement le carré : BC² = 50. Le nombre positif qui, au carré, donne 50 s’appelle la <b>racine carrée</b> de 50 : √50 ≈ 7,07.`,
  [T('Racine carrée',`<p>Pour un nombre a positif, <b>√a</b> est le nombre <b>positif</b> dont le carré vaut a. √25 = 5 car 5² = 25 ; √1,44 = 1,2 car 1,2² = 1,44.</p><p>Carrés parfaits à connaître : 1, 4, 9, 16, 25, 36, 49, 64, 81, 100, 121, 144, 169, 196, 225.</p>`),
   T('Encadrer, arrondir',`<p>Si a n’est pas un carré parfait, √a n’est pas entier ; on l’<b>encadre</b> entre deux entiers : 36 &lt; 40 &lt; 49 donc 6 &lt; √40 &lt; 7.</p><p>La calculatrice donne √40 ≈ 6,324 555… On donne une <b>valeur approchée</b> : arrondi au dixième 6,3 ; au centième 6,32. Pour arrondir, on regarde le chiffre suivant : 5 ou plus → on arrondit au-dessus.</p>`)],
  [{q:'Dans un triangle rectangle, l’hypoténuse vérifie BC² = 58. Donner BC arrondi au dixième.',s:['BC est positif donc BC = √58.','49 &lt; 58 &lt; 64, donc 7 &lt; √58 &lt; 8.','La calculatrice donne √58 ≈ 7,615 … ; arrondi au dixième : BC ≈ 7,6.']}],
  ['Je vérifie que le nombre est positif.','Je cherche s’il s’agit d’un carré parfait.','Sinon, j’encadre entre deux carrés parfaits, puis j’utilise la calculatrice.','J’arrondis à la précision demandée en regardant le chiffre suivant.'],
  ['Confondre racine carrée et moitié : √16 = 4, pas 8.','Tronquer au lieu d’arrondir : 6,38 arrondi au dixième donne 6,4.','Chercher √ d’un nombre négatif.'],
  ['√a est positif et (√a)² = a.','Encadrer avec les carrés parfaits voisins.','Arrondir : regarder le chiffre suivant (≥ 5 → au-dessus).']),
 g:mix([d=>{const k=d===1?R(1,12):d===2?R(10,15):P([0.2,0.3,0.4,0.6,0.7,0.8,1.1,1.2,1.3,1.5]);const a=Math.round(k*k*100)/100;return num(`Calcule √${nf(a)}.`,k,{expl:`${nf(k)}² = ${nf(a)} donc √${nf(a)} = <b>${nf(k)}</b>.`,hint:'Quel nombre positif, au carré, donne ce nombre ?'});},3],
  [d=>{const k=R(2,14),a=k*k+R(1,2*k);return ch(`Encadrement de √${a} par deux entiers consécutifs ?`,`${k} &lt; √${a} &lt; ${k+1}`,[`${k-1} &lt; √${a} &lt; ${k}`,`${k+1} &lt; √${a} &lt; ${k+2}`,`${Math.floor(a/2)} &lt; √${a} &lt; ${Math.floor(a/2)+1}`],{expl:`${k*k} &lt; ${a} &lt; ${(k+1)**2}, donc <b>${k} &lt; √${a} &lt; ${k+1}</b>.`,hint:'Cherche les carrés parfaits autour.'});},2],
  [d=>{const a=R(2,200);if(Number.isInteger(Math.sqrt(a)))return num(`Calcule √${a}.`,Math.sqrt(a),{expl:`${Math.sqrt(a)}² = ${a}.`});const p=P([1,2]);const v=Math.round(Math.sqrt(a)*10**p)/10**p;
   return num(`Donne l’arrondi ${p===1?'au dixième':'au centième'} de √${a}.`,v,{tol:0.5/10**p+1e-9,expl:`√${a} ≈ ${dec(Math.sqrt(a),4)} ; arrondi ${p===1?'au dixième':'au centième'} : <b>${nf(v)}</b>.`,hint:'Calculatrice, puis arrondi.'});},2],
  [d=>{const x=R(1000,99999)/1000;const p=P([0,1,2]);const v=Math.round(x*10**p)/10**p;return num(`Arrondis ${nf(x)} ${p===0?'à l’unité':p===1?'au dixième':'au centième'}.`,v,{expl:`On regarde le chiffre suivant la position demandée : <b>${nf(v)}</b>.`,hint:'5 ou plus → on arrondit au-dessus.'});},1],
  [bank([{tf:'√16 = 8.',v:false,e:'√16 = 4 car 4² = 16.'},['Entre quels entiers se trouve √2 ?','1 et 2',['2 et 3','0 et 1','1,4 et 1,5 seulement'],'1 &lt; 2 &lt; 4.'],{n:'Quel est le carré de 13 ?',a:169,e:'13 × 13 = 169.'}]),1])},

/* ======================= 4e ======================= */
{id:'4e',name:'Calcul littéral : réduire et développer',icon:'🔤',domain:'Nombres et calculs',
 refs:[REF,REP+' : « réduire une expression ; développer à l’aide de la (double) distributivité ; factoriser dans des cas simples »'],
 tip:'Avant de réduire, souligne d’une même couleur les termes « de la même famille » : les x², les x, les nombres.',
 c:C(`Le périmètre d’un rectangle de longueur x + 3 et de largeur x s’écrit 2(x + 3) + 2x. On peut l’écrire plus simplement : 4x + 6. Transformer une expression sans changer sa valeur, c’est le <b>calcul littéral</b>.`,
  [T('Réduire',`<p>On regroupe les termes de même nature : 3x + 5 − x + 2 = <b>2x + 7</b> ; 2x² + x − x² + 4x = <b>x² + 5x</b>.</p><p>Rappels : 3 × x = 3x ; x × x = x² ; 2x × 3x = 6x² ; x + x = 2x.</p>`),
   T('Développer',`<p>Simple distributivité : <b>k(a + b) = ka + kb</b> ; −2(x − 4) = −2x + 8.</p><p>Double distributivité : <b>(a + b)(c + d) = ac + ad + bc + bd</b> ; (x + 2)(x + 5) = x² + 5x + 2x + 10 = x² + 7x + 10.</p><p>Factoriser dans les cas simples : 5x + 15 = 5(x + 3).</p>`)],
  [{q:'Développer et réduire A = 3(2x − 1) − (x + 4).',s:['3(2x − 1) = 6x − 3.','−(x + 4) = −x − 4 (le signe − change tous les signes de la parenthèse).','A = 6x − 3 − x − 4 = 5x − 7.']}],
  ['Je développe chaque produit.','Je supprime les parenthèses précédées d’un signe − en changeant les signes.','Je regroupe et réduis.','Je teste avec x = 1 pour vérifier.'],
  ['Écrire x × x = 2x : c’est x².','Oublier de changer les signes après un −.','Additionner 3x et 2 : on ne peut pas.'],
  ['Réduire : regrouper les termes de même nature.','k(a + b) = ka + kb ; (a + b)(c + d) = ac + ad + bc + bd.','−(a + b) = −a − b.']),
 g:mix([d=>{const a=R(1,9),b=R(-9,9)||2,c=R(-6,6)||1,e=R(-9,9)||-4;return ch(`Réduis : <b>${lin(a,b)} ${c<0?'−':'+'} ${mono(Math.abs(c),'x')} ${e<0?'−':'+'} ${Math.abs(e)}</b>`,lin(a+c,b+e),[lin(a+c+b+e,0),lin(a-c,b+e),lin(a+c,b-e)],{expl:`x : ${a} ${c<0?'−':'+'} ${Math.abs(c)} = ${a+c} ; nombres : ${nf(b)} ${e<0?'−':'+'} ${Math.abs(e)} = ${nf(b+e)} → <b>${lin(a+c,b+e)}</b>.`,hint:'Regroupe les x, puis les nombres.'});},2],
  [d=>{const k=P([2,3,4,5,-2,-3,6]),a=R(1,6),b=R(-9,9)||3;return ch(`Développe : <b>${nf(k)}(${lin(a,b)})</b>`,lin(k*a,k*b),[lin(k*a,b),lin(k*a,-k*b),lin(a,k*b)],{expl:`${nf(k)} × ${mono(a,'x')} = ${mono(k*a,'x')} ; ${nf(k)} × ${par(b)} = ${nf(k*b)} → <b>${lin(k*a,k*b)}</b>.`,hint:'Distribue sur chaque terme.'});},2],
  [d=>{const b=R(-7,7)||3,e=R(-7,7)||-2;const B=b+e,Cc=b*e;return ch(`Développe et réduis : <b>(x ${b<0?'−':'+'} ${Math.abs(b)})(x ${e<0?'−':'+'} ${Math.abs(e)})</b>`,poly([1,'x²'],[B,'x'],[Cc,'']),[poly([1,'x²'],[Cc,'']),poly([1,'x²'],[B,'x'],[-Cc,'']),poly([2,'x'],[B,'x'],[Cc,''])].concat([poly([1,'x²'],[b-e,'x'],[Cc,''])]),{expl:`x × x = x² ; x × ${par(e)} + ${par(b)} × x = ${mono(B,'x')||'0'} ; ${par(b)} × ${par(e)} = ${nf(Cc)} → <b>${poly([1,'x²'],[B,'x'],[Cc,''])}</b>.`,hint:'Quatre produits.'});},2],
  [d=>{const a=R(1,6),b=R(-6,6)||2,c=R(1,5),e=R(-6,6)||1;return ch(`Développe et réduis : <b>${lin(a,b)} − (${lin(c,e)})</b>`,lin(a-c,b-e),[lin(a-c,b+e),lin(a+c,b-e),lin(a+c,b+e)],{expl:`−(${lin(c,e)}) = ${lin(-c,-e)} ; puis on réduit : <b>${lin(a-c,b-e)}</b>.`,hint:'Le signe − change tous les signes de la parenthèse.'});},1],
  [d=>{const k=P([2,3,4,5,6,7]);let a=R(1,6),b=R(1,9);while(gcd(a,b)!==1)b=R(1,9);return ch(`Factorise : <b>${lin(k*a,k*b)}</b>`,`${k}(${lin(a,b)})`,[`${k}(${lin(k*a,b)})`,`${k*a}(x + ${k*b})`,`x(${k*a} + ${k*b})`],{expl:`${k} divise ${k*a} et ${k*b} → <b>${k}(${lin(a,b)})</b>.`,hint:'Cherche le facteur commun.'});},1],
  [bank([['Que vaut 3x × 2x ?','6x²',['5x','6x','5x²'],'3 × 2 = 6 et x × x = x².'],['Pour x = 2, que vaut 3x² ?','12',['36','18','6'],'3 × 2² = 3 × 4 = 12 (le carré porte seulement sur x).',2]]),1])},

/* ======================= 4f ======================= */
{id:'4f',name:'Équations du premier degré',icon:'⚖️',domain:'Nombres et calculs',
 refs:[REF,REP+' : « résoudre algébriquement une équation du premier degré ; mettre un problème en équation »'],
 tip:'Imagine une balance : tout ce que tu fais d’un côté (ajouter, retirer, multiplier, diviser), tu dois le faire de l’autre.',
 c:C(`Léa a 3 fois plus de billes que Tom ; à eux deux ils en ont 48. Combien Tom en a-t-il ? En appelant x le nombre de billes de Tom : x + 3x = 48. Résoudre cette <b>équation</b>, c’est trouver x.`,
  [T('Principe',`<p>Une équation est une égalité qui contient une inconnue. Une <b>solution</b> est une valeur de l’inconnue qui rend l’égalité vraie.</p><p>On peut <b>ajouter ou soustraire</b> un même nombre aux deux membres, et <b>multiplier ou diviser</b> les deux membres par un même nombre non nul : les solutions ne changent pas.</p>`),
   T('Résoudre ax + b = cx + d',`<p>7x − 4 = 3x + 8 ⇔ 7x − 3x = 8 + 4 ⇔ 4x = 12 ⇔ x = 3.</p><p>On vérifie : 7 × 3 − 4 = 17 et 3 × 3 + 8 = 17 ✔.</p><p>Pour un problème : on choisit l’inconnue, on écrit l’équation, on la résout, on vérifie et on conclut par une phrase.</p>`)],
  [{q:'Résoudre 5(x − 2) = 2x + 11.',s:['On développe : 5x − 10 = 2x + 11.','5x − 2x = 11 + 10, donc 3x = 21.','x = 7. Vérification : 5 × 5 = 25 et 14 + 11 = 25 ✔.']}],
  ['Je développe si nécessaire.','Je regroupe les termes en x d’un côté, les nombres de l’autre.','Je divise par le coefficient de x.','Je vérifie dans l’équation de départ.'],
  ['Soustraire au lieu de diviser à la dernière étape : 4x = 12 donne x = 3, pas 8.','Faire une opération d’un seul côté.','Oublier de vérifier.'],
  ['Même opération des deux côtés.','ax = b ⇔ x = b ÷ a (a ≠ 0).','Vérifier puis conclure par une phrase.']),
 g:mix([d=>{const a=P([2,3,4,5,6,-2,-3]),x=R(-8,12),b=R(-15,15);const c=a*x+b;return num(`Résous : ${lin(a,b)} = ${nf(c)}. x = ?`,x,{expl:`${mono(a,'x')} = ${nf(c)} − ${par(b)} = ${nf(c-b)} ; x = ${nf(c-b)} ÷ ${par(a)} = <b>${nf(x)}</b>.`,hint:'Isole le terme en x.'});},3],
  [d=>{const x=R(-6,10);let a=R(2,9),c=R(1,8);if(a===c)a++;const b=R(-12,12),e=a*x+b-c*x;return num(`Résous : ${lin(a,b)} = ${lin(c,e)}. x = ?`,x,{expl:`On regroupe : ${mono(a,'x')} − ${mono(c,'x')} = ${nf(e)} − ${par(b)}, soit ${mono(a-c,'x')} = ${nf(e-b)}${a-c===1?'':`, donc x = ${nf(e-b)} ÷ ${par(a-c)}`} : <b>x = ${nf(x)}</b>.`,hint:'Les x d’un côté, les nombres de l’autre.'});},3],
  [d=>{const k=P([2,3,4,5]),t=R(4,30);return num(`Léa a ${k} fois plus de billes que Tom ; à eux deux, ils en ont ${(k+1)*t}. Combien Tom en a-t-il ?`,t,{expl:`x + ${k}x = ${(k+1)*t} donc ${k+1}x = ${(k+1)*t} et x = <b>${t}</b>.`,hint:'Appelle x le nombre de billes de Tom.'});},2],
  [d=>{const k=R(2,6),a=R(1,5),x=R(-4,9),c=k*(x-a);return num(`Résous : ${k}(x − ${a}) = ${nf(c)}. x = ?`,x,{expl:`${k}x − ${k*a} = ${nf(c)} ; ${k}x = ${nf(c+k*a)} ; x = <b>${nf(x)}</b>.`,hint:'Développe d’abord.'});},2],
  [bank([['Quelle est la solution de 4x = 0 ?','0',['4','−4','aucune'],'0 ÷ 4 = 0.'],{tf:'x = 2 est solution de 3x + 1 = 7.',v:true,e:'3 × 2 + 1 = 7.'}]),1])},

/* ======================= 4g ======================= */
{id:'4g',name:'Proportionnalité, quatrième proportionnelle et pourcentages',icon:'🔁',domain:'Organisation et gestion de données, fonctions',
 refs:[REF,REP+' : « reconnaître une situation de proportionnalité ; calculer une quatrième proportionnelle ; appliquer un pourcentage »'],
 tip:'Produit en croix : dans un tableau de proportionnalité a/b = c/x, on a x = b × c ÷ a.',
 c:C(`5 kg de pommes coûtent 12 € : combien coûtent 8 kg ? Si le prix est proportionnel à la masse, on peut le calculer de plusieurs façons. Les pourcentages sont, eux aussi, des situations de proportionnalité.`,
  [T('Reconnaître et calculer',`<p>Deux grandeurs sont <b>proportionnelles</b> si l’on passe de l’une à l’autre en multipliant toujours par le même nombre (coefficient de proportionnalité).</p><p><b>Quatrième proportionnelle</b> : si 5 kg ↔ 12 €, alors 8 kg ↔ x € avec x = 8 × 12 ÷ 5 = <b>19,20 €</b> (produit en croix). On peut aussi passer par l’unité : 1 kg ↔ 2,40 €.</p>`),
   T('Pourcentages',`<p>t % d’un nombre = nombre × t/100 : 15 % de 80 = 80 × 0,15 = 12.</p><p>Exprimer une proportion en pourcentage : 9 sur 36 = 9/36 = 0,25 = <b>25 %</b>.</p><p>Augmenter de t % : × (1 + t/100) ; diminuer de t % : × (1 − t/100).</p>`)],
  [{q:'Un tableau : 3 L ↔ 4,50 € ; 7 L ↔ ? €. Calculer.',s:['C’est une situation de proportionnalité (prix au litre constant).','Prix pour 1 L : 4,50 ÷ 3 = 1,50 €.','Pour 7 L : 7 × 1,50 = 10,50 €.']}],
  ['Je vérifie que la situation est proportionnelle.','Je choisis une méthode : coefficient, passage par l’unité ou produit en croix.','Je calcule et j’écris l’unité.','Je contrôle l’ordre de grandeur.'],
  ['Utiliser le produit en croix dans une situation non proportionnelle (âge et taille…).','Ajouter au lieu de multiplier : si 2 kg ↔ 5 €, 4 kg ↔ 10 €, pas 7 €.','Confondre « 20 % de » et « augmenté de 20 % ».'],
  ['Proportionnel : on multiplie toujours par le même nombre.','Produit en croix : x = b × c ÷ a.','t % de N = N × t/100.']),
 g:mix([d=>{const u=P([1.2,1.5,2,2.4,2.5,3,3.5,4,0.8]),a=R(2,6);let b=R(3,12);if(b===a)b++;const pa=Math.round(u*a*100)/100;const pb=Math.round(u*b*100)/100;return num(`${a} kg coûtent ${nf(pa)} €. Le prix est proportionnel à la masse. Combien coûtent ${b} kg ?`,pb,{unit:'€',expl:`Prix au kg : ${nf(pa)} ÷ ${a} = ${nf(u)} € ; ${b} × ${nf(u)} = <b>${nf(pb)} €</b>.`,hint:'Passe par l’unité ou fais un produit en croix.'});},3],
  [d=>{const t=P([5,10,12,15,20,25,30,40,75]),n=P([40,60,80,120,150,200,240,360]);return num(`Calcule ${t} % de ${n}.`,n*t/100,{expl:`${n} × ${nf(t/100)} = <b>${nf(n*t/100)}</b>.`,hint:`${t} % = ${t}/100.`});},2],
  [d=>{const combos=[];for(const t of [20,25,40,50,80,200])for(const q of [5,10,20,25,40,50,75])if(t*q%100===0)combos.push([t,q]);const [tot,p]=P(combos);const part=tot*p/100;return num(`${part} élèves sur ${tot} pratiquent un sport. Quel pourcentage cela représente-t-il ?`,p,{unit:'%',expl:`${part} ÷ ${tot} = ${nf(p/100)} = <b>${p} %</b>.`,hint:'Part ÷ total × 100.'});},2],
  [d=>{const k=P([1.5,2,3,0.5,4]);const xs=[2,4,6,10];const ys=xs.map(x=>x*k);const prop=Math.random()<.5;if(!prop)ys[R(1,3)]+=1;return ch(`<table class="ptable"><tr><th>x</th>${xs.map(x=>`<td>${x}</td>`).join('')}</tr><tr><th>y</th>${ys.map(y=>`<td>${nf(y)}</td>`).join('')}</tr></table>Ce tableau est-il un tableau de proportionnalité ?`,prop?'Oui':'Non',[prop?'Non':'Oui'],{expl:prop?`y = ${nf(k)} × x pour chaque colonne.`:'Les quotients y ÷ x ne sont pas tous égaux.',hint:'Calcule y ÷ x pour chaque colonne.'});},2],
  [bank([['L’âge et la taille d’un enfant sont-ils proportionnels ?','non',['oui','seulement avant 10 ans','oui, coefficient 10'],'La taille n’est pas multipliée par 2 quand l’âge double.'],['Un prix de 50 € augmente de 20 %. Nouveau prix ?','60 €',['70 €','52 €','40 €'],'50 × 1,2 = 60.',2]]),1])},

/* ======================= 4h ======================= */
{id:'4h',name:'Vitesse, débit et grandeurs quotients',icon:'🏎️',domain:'Grandeurs et mesures',
 refs:[REF,REP+' : « calculer avec des grandeurs quotients (vitesse moyenne, débit) ; conversions d’unités de durée »'],
 tip:'Convertis toujours les durées en heures décimales (ou en minutes) avant de calculer : 45 min = 0,75 h.',
 c:C(`Un coureur parcourt 10 km en 50 minutes ; un robinet remplit un seau de 12 L en 3 minutes. La <b>vitesse moyenne</b> et le <b>débit</b> sont des grandeurs quotients : une quantité divisée par une durée.`,
  [T('Vitesse moyenne',`<p><b>v = d ÷ t</b>. Unités : km/h, m/s. On en déduit d = v × t et t = d ÷ v.</p><p>10 km en 50 min : 50 min = 50/60 h ; v = 10 ÷ (50/60) = 12 km/h.</p><p>Durées : 1 h = 60 min ; 30 min = 0,5 h ; 15 min = 0,25 h ; 45 min = 0,75 h ; 20 min = 1/3 h.</p>`),
   T('Débit',`<p>Débit = volume ÷ durée (L/min, m³/h). 12 L en 3 min : 4 L/min. Le temps pour remplir 100 L à 4 L/min : 100 ÷ 4 = 25 min.</p>`)],
  [{q:'Un cycliste roule 1 h 15 min à 24 km/h. Quelle distance parcourt-il ?',s:['1 h 15 min = 1,25 h.','d = v × t = 24 × 1,25.','d = 30 km.']}],
  ['J’identifie la formule (v = d ÷ t ou débit = V ÷ t).','Je convertis les durées.','Je calcule avec les unités.','Je vérifie que le résultat est réaliste.'],
  ['Écrire 1 h 15 min = 1,15 h.','Confondre vitesse et distance.','Oublier l’unité dans la réponse.'],
  ['v = d ÷ t ; d = v × t ; t = d ÷ v.','Débit = volume ÷ durée.','15 min = 0,25 h ; 45 min = 0,75 h.']),
 g:mix([d=>{const v=P([10,12,15,20,30,40,50,60,80,90,100]),t=P([0.25,0.5,0.75,1,1.5,2,3]);const th=t<1?`${t*60} min`:t%1?`${Math.floor(t)} h ${(t%1)*60} min`:`${t} h`;const w=P(['d','v']);
   return w==='d'?num(`À ${v} km/h pendant ${th}, quelle distance parcourt-on ?`,v*t,{unit:'km',expl:`${th} = ${nf(t)} h ; d = ${v} × ${nf(t)} = <b>${nf(v*t)} km</b>.`,hint:'d = v × t (t en heures).'}):num(`On parcourt ${nf(v*t)} km en ${th}. Quelle est la vitesse moyenne ?`,v,{unit:'km/h',expl:`v = ${nf(v*t)} ÷ ${nf(t)} = <b>${v} km/h</b>.`,hint:'v = d ÷ t.'});},3],
  [d=>{const deb=P([2,3,4,5,6,8,10,12]),t=P([3,4,5,6,8,10,15]);return num(`Un robinet remplit ${deb*t} L en ${t} min. Quel est son débit ?`,deb,{unit:'L/min',expl:`${deb*t} ÷ ${t} = <b>${deb} L/min</b>.`,hint:'Volume ÷ durée.'});},2],
  [d=>{const v=P([12,15,20,30,40,60]),dd=v*P([0.5,1.5,2,2.5,3]);return num(`Combien d’heures faut-il pour parcourir ${nf(dd)} km à ${v} km/h ? (réponse décimale)`,dd/v,{unit:'h',expl:`t = ${nf(dd)} ÷ ${v} = <b>${nf(dd/v)} h</b>.`,hint:'t = d ÷ v.'});},2],
  [d=>{const m=P([15,30,45,12,20,36,40]);return num(`Convertis ${m} min en heures (écriture décimale).`,m/60,{unit:'h',expl:`${m} ÷ 60 = <b>${nf(m/60)} h</b>.`,hint:'Divise par 60.'});},1],
  [bank([['1 h 30 min correspond à…','1,5 h',['1,3 h','1,03 h','130 min'],'30 min = 0,5 h.'],{tf:'Une vitesse de 36 km/h correspond à 10 m/s.',v:true,e:'36 000 m en 3 600 s : 10 m/s.',d:3}]),1])},

/* ======================= 4i ======================= */
{id:'4i',name:'Fonctions : formule, tableau et graphique',icon:'📈',domain:'Organisation et gestion de données, fonctions',
 refs:[REF,REP+' : « exprimer une dépendance entre deux grandeurs par une formule, un tableau ou un graphique ; lire et calculer des images »'],
 tip:'Une formule comme f(x) = 3x + 2 est une machine : on entre x, on obtient f(x). Pour lire un graphique, pars toujours de l’axe horizontal.',
 c:C(`Le prix d’un trajet en taxi dépend de la distance ; la température dépend de l’heure de la journée. Quand une grandeur dépend d’une autre, on peut décrire ce lien par une <b>formule</b>, un <b>tableau de valeurs</b> ou un <b>graphique</b>.`,
  [T('Formule et tableau',`<p>Une formule permet de calculer : si le prix est p = 2x + 3 (x en km), pour 5 km : p = 2 × 5 + 3 = 13 €.</p><p>On peut écrire f(x) = 2x + 3 et dire que <b>13 est l’image de 5</b> par f : f(5) = 13.</p><p>Un tableau de valeurs rassemble plusieurs calculs : x = 0, 1, 2, 5 donne f(x) = 3, 5, 7, 13.</p>`),
   T('Graphique',`<p>Chaque couple (x ; f(x)) donne un point du graphique. On lit l’image d’un nombre en partant de l’axe des abscisses, en rejoignant la courbe, puis en lisant l’ordonnée.</p><p>Inversement, pour trouver quel x donne une valeur, on part de l’axe des ordonnées.</p>`)],
  [{q:'f(x) = x² − 1. Compléter un tableau pour x = −2, 0 et 3.',s:['f(−2) = (−2)² − 1 = 4 − 1 = 3.','f(0) = 0 − 1 = −1.','f(3) = 9 − 1 = 8.']}],
  ['Je repère la formule ou le tableau.','Je remplace x par la valeur (entre parenthèses si elle est négative).','Je calcule en respectant les priorités.','Sur un graphique, je pars de l’axe horizontal pour lire une image.'],
  ['Calculer −2² au lieu de (−2)².','Lire le graphique en partant du mauvais axe.','Confondre f(5) et 5 × f.'],
  ['f(x) se calcule en remplaçant x.','Point du graphique : (x ; f(x)).','Image : lue sur l’axe vertical.']),
 g:mix([d=>{const a=R(-5,6)||2,b=R(-8,8),x=R(-5,6);return num(`f(x) = ${lin(a,b)}. Calcule f(${nf(x)}).`,a*x+b,{expl:`f(${nf(x)}) = ${nf(a)} × ${par(x)} ${b<0?'−':'+'} ${Math.abs(b)} = <b>${nf(a*x+b)}</b>.`,hint:'Remplace x par le nombre.'});},3],
  [d=>{const b=R(-5,5),x=R(-4,5);return num(`g(x) = ${poly([1,'x²'],[b,''])}. Calcule g(${nf(x)}).`,x*x+b,{expl:`g(${nf(x)}) = ${par(x)}² ${b<0?'−':'+'} ${Math.abs(b)} = ${x*x} ${b<0?'−':'+'} ${Math.abs(b)} = <b>${nf(x*x+b)}</b>.`,hint:'Un carré est positif.'});},2],
  [d=>{const a=R(-3,3)||1,b=R(-4,4);const xs=[-1,0,1,2,3];const ys=xs.map(x=>a*x+b);const i=R(0,4);return num(`<table class="ptable"><tr><th>x</th>${xs.map(x=>`<td>${nf(x)}</td>`).join('')}</tr><tr><th>f(x)</th>${ys.map(y=>`<td>${nf(y)}</td>`).join('')}</tr></table>Quelle est l’image de ${nf(xs[i])} ?`,ys[i],{expl:`Colonne x = ${nf(xs[i])} : f(x) = <b>${nf(ys[i])}</b>.`,hint:'Lis la ligne f(x).'});},2],
  [d=>{const a=P([1,-1,2,0.5,-2]),b=R(-2,2);const xs=[-2,-1,0,1,2].filter(x=>Number.isInteger(a*x+b)&&Math.abs(a*x+b)<=5);const x=P(xs);return num(`${graph([[a,b]])}Lis sur le graphique l’image de <b>${nf(x)}</b>.`,a*x+b,{expl:`On part de x = ${nf(x)}, on rejoint la droite, on lit l’ordonnée : <b>${nf(a*x+b)}</b>.`,hint:'Pars de l’axe horizontal.'});},2],
  [d=>{const p=P([2,2.5,3]),f=P([2,3,4]),k=R(3,12);return num(`Un taxi coûte ${nf(f)} € de prise en charge plus ${nf(p)} € par km. Combien coûte un trajet de ${k} km ?`,f+p*k,{unit:'€',expl:`p = ${nf(p)} × ${k} + ${nf(f)} = <b>${nf(f+p*k)} €</b>.`,hint:'Prix fixe + prix par km × nombre de km.'});},1],
  [bank([['f(3) = 10 signifie…','10 est l’image de 3',['3 est l’image de 10','f = 30','3 × 10 = f'],'f(3) se lit « f de 3 ».'],['Sur un graphique, le point (2 ; 5) signifie que…','f(2) = 5',['f(5) = 2','2 + 5 = f','f vaut 7'],'L’abscisse est x, l’ordonnée est f(x).']]),1])},

/* ======================= 4j ======================= */
{id:'4j',name:'Statistiques : moyenne pondérée',icon:'📊',domain:'Organisation et gestion de données, fonctions',
 refs:[REF,REP+' : « calculer une moyenne, une moyenne pondérée ; fréquences »'],
 tip:'Moyenne pondérée : multiplie chaque valeur par son effectif (ou son coefficient), additionne tout, puis divise par la somme des effectifs (ou des coefficients).',
 c:C(`Au bulletin, une note de contrôle compte souvent plus qu’une note d’exercice : elle a un <b>coefficient</b>. Pour calculer la moyenne dans ce cas, on utilise une <b>moyenne pondérée</b>.`,
  [T('Moyenne simple et pondérée',`<p>Moyenne simple : somme des valeurs ÷ nombre de valeurs. 12, 15, 9 → (12 + 15 + 9) ÷ 3 = 12.</p><p>Moyenne pondérée : (12 × 1 + 15 × 2 + 9 × 3) ÷ (1 + 2 + 3) = (12 + 30 + 27) ÷ 6 = 69 ÷ 6 = <b>11,5</b>.</p><p>Avec un tableau d’effectifs, chaque valeur est « pondérée » par son effectif.</p>`),
   T('Fréquences',`<p>La <b>fréquence</b> d’une valeur = effectif de la valeur ÷ effectif total. Elle s’exprime en fraction, en décimal ou en pourcentage : 6 élèves sur 24 → 6/24 = 0,25 = 25 %.</p><p>La somme de toutes les fréquences vaut 1 (100 %).</p>`)],
  [{q:'Notes : 14 (coef. 2), 8 (coef. 1), 11 (coef. 3). Moyenne ?',s:['Somme pondérée : 14 × 2 + 8 × 1 + 11 × 3 = 28 + 8 + 33 = 69.','Somme des coefficients : 2 + 1 + 3 = 6.','Moyenne : 69 ÷ 6 = 11,5.']}],
  ['Je multiplie chaque valeur par son coefficient (ou effectif).','J’additionne ces produits.','Je divise par la somme des coefficients.','Je vérifie que la moyenne est entre la plus petite et la plus grande valeur.'],
  ['Diviser par le nombre de valeurs au lieu de la somme des coefficients.','Oublier de multiplier une des valeurs.','Trouver une moyenne en dehors des valeurs extrêmes.'],
  ['Moyenne pondérée = Σ(valeur × coef.) ÷ Σ coef.','Fréquence = effectif ÷ effectif total.','La moyenne est comprise entre min et max.']),
 g:mix([d=>{const n=d===1?3:4;const v=Array.from({length:n},()=>R(4,19));const c=Array.from({length:n},()=>R(1,4));const S=v.reduce((a,x,i)=>a+x*c[i],0),W=c.reduce((a,b)=>a+b,0);const m=Math.round(S/W*100)/100;
   return num(`Notes : ${v.map((x,i)=>`${x} (coef. ${c[i]})`).join(', ')}. Calcule la moyenne, arrondie au centième.`,m,{tol:0.0051,expl:`Σ = ${v.map((x,i)=>`${x} × ${c[i]}`).join(' + ')} = ${S} ; Σ coef. = ${W} ; moyenne ≈ <b>${nf(m)}</b>.`,hint:'Multiplie chaque note par son coefficient.'});},3],
  [d=>{const vals=[1,2,3,4];const eff=vals.map(()=>R(1,8));const N=eff.reduce((a,b)=>a+b,0);const S=vals.reduce((a,v,i)=>a+v*eff[i],0);const m=Math.round(S/N*100)/100;
   return num(`<table class="ptable"><tr><th>Nombre de frères et sœurs</th>${vals.map(v=>`<td>${v}</td>`).join('')}</tr><tr><th>Effectif</th>${eff.map(e=>`<td>${e}</td>`).join('')}</tr></table>Nombre moyen de frères et sœurs, arrondi au centième ?`,m,{tol:0.0051,expl:`Σ valeur × effectif = ${S} ; effectif total ${N} ; moyenne ≈ <b>${nf(m)}</b>.`,hint:'Pondère par les effectifs.'});},2],
  [d=>{const tot=P([20,25,40,50]),e=R(2,tot/2);return num(`Dans une classe de ${tot} élèves, ${e} ont un chat. Quelle est la fréquence en pourcentage ?`,e/tot*100,{unit:'%',expl:`${e} ÷ ${tot} = ${nf(e/tot)} = <b>${nf(e/tot*100)} %</b>.`,hint:'Effectif ÷ total × 100.'});},2],
  [d=>{const v=Array.from({length:R(4,6)},()=>R(5,20));let s=v.reduce((a,b)=>a+b,0);const n=v.length;if(s%n){v[0]+=n-s%n;s=v.reduce((a,b)=>a+b,0);}return num(`Calcule la moyenne de : ${v.join(' ; ')}.`,s/n,{expl:`${s} ÷ ${n} = <b>${s/n}</b>.`,hint:'Somme ÷ nombre de valeurs.'});},1],
  [bank([{tf:'La moyenne d’une série peut être plus grande que sa plus grande valeur.',v:false,e:'Elle est toujours entre le minimum et le maximum.'},['La somme des fréquences d’une série vaut…','1 (soit 100 %)',['l’effectif total','la moyenne','0'],'Chaque fréquence est une part du total : toutes les parts réunies font le tout, soit 1.']]),1])},

/* ======================= 4k ======================= */
{id:'4k',name:'Médiane, étendue et comparaison de séries',icon:'📏',domain:'Organisation et gestion de données, fonctions',
 refs:[REF,REP+' : « déterminer une médiane et une étendue ; comparer deux séries »'],
 tip:'Pas de médiane sans série rangée ! Avec n valeurs : si n est impair, la médiane est la valeur de rang (n + 1) ÷ 2.',
 c:C(`Deux joueurs de basket ont la même moyenne de points par match. Lequel est le plus régulier ? La <b>médiane</b> et l’<b>étendue</b> permettent de comparer plus finement deux séries.`,
  [T('Médiane',`<p>La médiane partage la série <b>rangée</b> en deux parties de même effectif.</p><p>7 valeurs : 3 ; 5 ; 6 ; 9 ; 12 ; 14 ; 20 → la 4e valeur, <b>9</b>.</p><p>6 valeurs : 3 ; 5 ; 6 ; 9 ; 12 ; 14 → médiane entre la 3e et la 4e : (6 + 9) ÷ 2 = <b>7,5</b>.</p>`),
   T('Étendue et comparaison',`<p>Étendue = plus grande valeur − plus petite valeur. Plus elle est petite, plus la série est <b>regroupée</b> (régulière).</p><p>Pour comparer deux séries : on compare moyennes et médianes (le niveau), puis étendues (la dispersion).</p>`)],
  [{q:'Joueur A : 10 ; 12 ; 14 ; 12 ; 12. Joueur B : 2 ; 20 ; 12 ; 22 ; 4. Comparer.',s:['Moyennes : A 60 ÷ 5 = 12 ; B 60 ÷ 5 = 12.','Médianes : A 12 ; B (rangée 2 ; 4 ; 12 ; 20 ; 22) 12.','Étendues : A 14 − 10 = 4 ; B 22 − 2 = 20 : A est bien plus régulier.']}],
  ['Je range la série.','Je calcule la médiane selon la parité de l’effectif.','Je calcule l’étendue.','Je compare et j’interprète par une phrase.'],
  ['Prendre la valeur du milieu sans ranger la série.','Confondre étendue et plus grande valeur.','Conclure qu’un joueur est meilleur en ne regardant que l’étendue.'],
  ['Médiane : série rangée, valeur du milieu.','Étendue = max − min (dispersion).','Comparer : niveau (moyenne, médiane) et régularité (étendue).']),
 g:mix([d=>{const n=P(d===1?[5,7]:[6,8,9]);const v=Array.from({length:n},()=>R(1,40));const s=v.slice().sort((a,b)=>a-b);const med=n%2?s[(n-1)/2]:(s[n/2-1]+s[n/2])/2;
   return num(`Médiane de la série : ${v.join(' ; ')} ?`,med,{expl:`Rangée : ${s.join(' ; ')} → <b>${nf(med)}</b>.`,hint:'Range d’abord.'});},3],
  [d=>{const v=Array.from({length:R(5,9)},()=>R(1,50));return num(`Étendue de la série : ${v.join(' ; ')} ?`,Math.max(...v)-Math.min(...v),{expl:`${Math.max(...v)} − ${Math.min(...v)} = <b>${Math.max(...v)-Math.min(...v)}</b>.`,hint:'Max − min.'});},2],
  [d=>{const base=R(10,14);const A=[base-1,base,base,base+1,base];const sp=R(6,10);const B=[base-sp,base+sp,base,base-2,base+2];const sA=Math.max(...A)-Math.min(...A),sB=Math.max(...B)-Math.min(...B);
   return ch(`Joueur A : ${shuffle(A).join(' ; ')}. Joueur B : ${shuffle(B).join(' ; ')}. Même moyenne (${base}). Quel joueur est le plus régulier ?`,'A',['B','les deux autant'],{expl:`Étendues : A = ${sA}, B = ${sB}. La plus petite étendue indique le plus régulier : <b>A</b>.`,hint:'Compare les étendues.'});},2],
  [bank([['Une série a 9 valeurs rangées. La médiane est la…','5e valeur',['4e valeur','4,5e valeur','9e valeur'],'(9 + 1) ÷ 2 = 5.'],['Une série a 10 valeurs rangées. La médiane est…','la moyenne des 5e et 6e valeurs',['la 5e valeur','la 10e valeur','la moyenne de toutes les valeurs'],'Effectif pair : moyenne des deux valeurs centrales.'],{tf:'La médiane est toujours égale à la moyenne.',v:false,e:'1 ; 2 ; 30 : médiane 2, moyenne 11.'}]),1])},

/* ======================= 4l ======================= */
{id:'4l',name:'Probabilités, évènement contraire et simulations',icon:'🎲',domain:'Organisation et gestion de données, fonctions',
 refs:[REF,REP+' : « calculer des probabilités dans des situations simples ; évènement contraire ; lien fréquence-probabilité »'],
 tip:'P(non A) = 1 − P(A) : souvent plus rapide que de compter toutes les issues de « non A ».',
 c:C(`On tire une carte au hasard dans un jeu de 32 cartes. Quelle chance d’obtenir un cœur ? de ne pas obtenir un as ? Les <b>probabilités</b> mesurent la chance qu’un évènement se réalise, par un nombre entre 0 et 1.`,
  [T('Calculer une probabilité',`<p>Quand toutes les issues ont la même chance (équiprobabilité) : <b>P(A) = nombre d’issues favorables ÷ nombre total d’issues</b>.</p><p>Jeu de 32 cartes : 8 cœurs → P(cœur) = 8/32 = 1/4 ; 4 as → P(as) = 4/32 = 1/8.</p><p>0 ≤ P(A) ≤ 1 ; un évènement impossible a une probabilité 0, un évènement certain 1.</p>`),
   T('Évènement contraire et fréquence',`<p>L’évènement contraire de A, noté « non A », se réalise quand A ne se réalise pas : <b>P(non A) = 1 − P(A)</b>. P(pas d’as) = 1 − 1/8 = 7/8.</p><p>Quand on répète une expérience un grand nombre de fois, la <b>fréquence</b> observée se rapproche de la probabilité (simulation sur tableur ou Scratch).</p>`)],
  [{q:'Un sac contient 3 billes rouges, 5 vertes et 2 bleues. P(verte) ? P(pas rouge) ?',s:['10 billes en tout.','P(verte) = 5/10 = 1/2.','P(rouge) = 3/10 donc P(pas rouge) = 1 − 3/10 = 7/10.']}],
  ['Je compte le nombre total d’issues équiprobables.','Je compte les issues favorables.','Je calcule et je simplifie la fraction.','Pour un évènement contraire, je fais 1 − P(A).'],
  ['Oublier une couleur dans le total.','Donner une probabilité supérieure à 1.','Croire qu’après plusieurs « pile », « face » devient plus probable.'],
  ['P(A) = favorables ÷ total.','P(non A) = 1 − P(A).','La fréquence tend vers la probabilité quand on répète beaucoup.']),
 g:mix([d=>{const r=R(1,8),v=R(1,8),b=R(1,6);const tot=r+v+b;const c=P([['rouge',r],['verte',v],['bleue',b]]);return fracR(`Un sac contient ${r} bille${r>1?'s':''} rouge${r>1?'s':''}, ${v} verte${v>1?'s':''} et ${b} bleue${b>1?'s':''}. On tire une bille au hasard. Probabilité qu’elle soit ${c[0]} ?`,c[1],tot,{expl:`${c[1]} bille${c[1]>1?'s':''} ${c[0]}${c[1]>1?'s':''} sur ${tot} : P = <b>${c[1]}/${tot}${eqF(c[1],tot)}</b>.`,hint:'Favorables ÷ total.'});},3],
  [d=>{const n=P([10,20,25,50,100]),k=R(1,n-1);return fracR(`P(A) = ${k}/${n}. Quelle est la probabilité de l’évènement contraire ?`,n-k,n,{expl:`1 − ${k}/${n} = <b>${fr(n-k,n)}</b>.`,hint:'1 − P(A).'});},2],
  [d=>{const e=P([['un nombre pair',3],['un multiple de 3',2],['un nombre supérieur à 4',2],['un 6',1],['un nombre premier',3],['un nombre inférieur à 3',2]]);return fracR(`On lance un dé équilibré à 6 faces. Probabilité d’obtenir ${e[0]} ?`,e[1],6,{expl:`${e[1]} issue${e[1]>1?'s':''} favorable${e[1]>1?'s':''} sur 6 : P = <b>${fr(e[1],6)}</b>.`,hint:'Liste les faces qui conviennent.'});},2],
  [d=>{const cards=P([['un cœur',8],['un as',4],['une figure (valet, dame, roi)',12],['une carte rouge',16],['le roi de pique',1]]);return fracR(`On tire une carte dans un jeu de 32 cartes. Probabilité de tirer ${cards[0]} ?`,cards[1],32,{expl:`${cards[1]} cartes favorables sur 32 : P = <b>${fr(cards[1],32)}</b>.`,hint:'Un jeu de 32 cartes : 4 couleurs de 8 cartes.'});},1],
  [bank([['Quelle valeur ne peut pas être une probabilité ?','1,2',['0','0,5','1'],'Une probabilité est entre 0 et 1.'],{tf:'Après 4 « pile » de suite, « face » est plus probable.',v:false,e:'Les lancers sont indépendants : toujours 1/2.'},['On lance 1 000 fois une pièce équilibrée. La fréquence de « pile » sera probablement…','proche de 0,5',['exactement 0,5','proche de 0,1','égale à 1'],'La fréquence fluctue autour de la probabilité.']]),1])},

/* ======================= 4m ======================= */
{id:'4m',name:'Repérage dans le plan et l’espace',icon:'🧭',domain:'Espace et géométrie',
 refs:[REF,REP+' : « se repérer dans le plan (abscisse, ordonnée) et dans un pavé droit (abscisse, ordonnée, altitude) »'],
 tip:'Dans le plan : d’abord l’abscisse (horizontal), puis l’ordonnée (vertical). Dans l’espace, on ajoute l’altitude (hauteur).',
 c:C(`Au jeu de la bataille navale, « B5 » repère une case. En mathématiques, on repère un point du plan par deux nombres, ses <b>coordonnées</b>, et un point de l’espace par trois nombres.`,
  [T('Dans le plan',`<p>Un repère est formé de deux axes gradués perpendiculaires qui se coupent à l’origine O. Le point A(3 ; −2) a pour <b>abscisse</b> 3 (axe horizontal) et pour <b>ordonnée</b> −2 (axe vertical).</p><p>Les points de l’axe des abscisses ont une ordonnée nulle ; ceux de l’axe des ordonnées, une abscisse nulle.</p>`),
   T('Dans l’espace (pavé droit)',`<p>Dans un pavé droit, on repère un point par trois coordonnées : <b>abscisse, ordonnée, altitude</b>. Un sommet d’un pavé de 4 × 3 × 2 placé à l’origine a pour coordonnées (0 ; 0 ; 0), (4 ; 0 ; 0), (4 ; 3 ; 0), (4 ; 3 ; 2)…</p><p>Sur la Terre, on utilise un autre repérage : latitude et longitude (étudié en 3e).</p>`)],
  [{q:'Un pavé a ses arêtes de longueurs 5, 3 et 4 le long des axes, avec un sommet en O. Coordonnées du sommet opposé à O ?',s:['Il faut avancer de 5 en abscisse.','Puis de 3 en ordonnée.','Puis de 4 en altitude : (5 ; 3 ; 4).']}],
  ['Je repère les axes et leur ordre.','Je lis l’abscisse puis l’ordonnée (puis l’altitude).','Je fais attention aux signes (gauche ou bas : négatif).','J’écris les coordonnées entre parenthèses séparées par « ; ».'],
  ['Inverser abscisse et ordonnée.','Oublier le signe moins pour un point à gauche ou en bas de l’origine.','Oublier l’altitude dans l’espace.'],
  ['Point du plan : (abscisse ; ordonnée).','Point de l’espace : (abscisse ; ordonnée ; altitude).','Origine : (0 ; 0) ou (0 ; 0 ; 0).']),
 g:mix([d=>{const x=(R(1,5))*P([1,-1]),y=(R(1,5))*P([1,-1]);const Q=['à droite et en haut','à droite et en bas','à gauche et en haut','à gauche et en bas'];const good=`${x>0?'à droite':'à gauche'} et ${y>0?'en haut':'en bas'}`;return ch(`Où se trouve le point A(${nf(x)} ; ${nf(y)}) par rapport à l’origine ?`,good,Q.filter(q=>q!==good),{expl:`Abscisse ${nf(x)} : ${x>0?'à droite':'à gauche'} ; ordonnée ${nf(y)} : ${y>0?'en haut':'en bas'}.`,hint:'L’abscisse est horizontale, l’ordonnée verticale.'});},2],
  [d=>{const a=P([1,-1,2,0.5]),b=R(-2,2);const xs=[-2,-1,0,1,2].filter(x=>Number.isInteger(a*x+b)&&Math.abs(a*x+b)<=5);const x=P(xs),y=a*x+b;return multiP(`${graph([[a,b]])}Le point de la droite d’abscisse ${nf(x)} a pour coordonnées…`,x,y);},2],
  [d=>{const L=R(2,9),l=R(2,9),h=R(2,9);const pts=[['du sommet opposé à O',[L,l,h]],['du sommet situé sur l’axe des abscisses, autre que O',[L,0,0]],['du sommet situé juste au-dessus de O',[0,0,h]],['du sommet de la face du bas opposé à O',[L,l,0]]];const [nm,c]=P(pts);
   return ch(`Un pavé droit de dimensions ${L} (abscisses) × ${l} (ordonnées) × ${h} (altitudes) a un sommet en O(0 ; 0 ; 0). Coordonnées ${nm} ?`,`(${c.join(' ; ')})`,[`(${[c[1],c[0],c[2]].join(' ; ')})`,`(${[c[0],c[2],c[1]].join(' ; ')})`,`(${[L,l,h].map(v=>v+1).join(' ; ')})`],{expl:`On avance de ${c[0]} en abscisse, ${c[1]} en ordonnée, ${c[2]} en altitude : <b>(${c.join(' ; ')})</b>.`,hint:'Ordre : abscisse, ordonnée, altitude.'});},2],
  [bank([['Le point B(0 ; 4) est situé…','sur l’axe des ordonnées',['sur l’axe des abscisses','à l’origine','en bas à gauche'],'Son abscisse est nulle.'],['Dans l’espace, la troisième coordonnée s’appelle…','l’altitude',['la latitude','l’abscisse','la longitude'],'Abscisse, ordonnée, altitude : l’altitude mesure la « hauteur » du point.'],{tf:'Les points (2 ; 5) et (5 ; 2) sont confondus.',v:false,e:'L’ordre des coordonnées compte.'}]),1])},

/* ======================= 4n ======================= */
{id:'4n',name:'Agrandissements, réductions et translation',icon:'🔎',domain:'Espace et géométrie',
 refs:[REF,REP+' : « comprendre l’effet d’une translation ; agrandissements et réductions (effet sur les longueurs, les aires, les volumes) »'],
 tip:'Rapport k : longueurs × k, aires × k², volumes × k³. Une translation, elle, fait « glisser » la figure sans la tourner ni changer sa taille.',
 c:C(`Un plan de maison, une maquette de train, une photo imprimée en plus grand : ce sont des <b>réductions</b> ou des <b>agrandissements</b>. Dans une frise, un motif répété en glissant illustre une <b>translation</b>.`,
  [T('Agrandissement et réduction',`<p>Agrandir ou réduire de rapport k, c’est multiplier toutes les longueurs par k (k &gt; 1 : agrandissement ; 0 &lt; k &lt; 1 : réduction). Les angles sont conservés.</p><p>Les <b>aires</b> sont multipliées par <b>k²</b>, les <b>volumes</b> par <b>k³</b>. Un cube de 2 cm agrandi de rapport 3 : arête 6 cm, aire d’une face × 9, volume × 27.</p>`),
   T('Translation',`<p>Une translation fait glisser une figure selon une direction, un sens et une longueur donnés (par exemple « de A vers B »). L’image est superposable à la figure : longueurs, angles, aires et parallélisme sont conservés.</p><p>Dans un quadrillage : « 3 carreaux à droite et 2 vers le haut » ; un point (x ; y) devient (x + 3 ; y + 2).</p>`)],
  [{q:'Une maquette au 1/50 d’un bâtiment : une pièce de 4 m de long mesure combien sur la maquette ? Et une surface de 20 m² ?',s:['Longueurs × 1/50 : 4 m = 400 cm ; 400 ÷ 50 = 8 cm.','Aires × (1/50)² = 1/2 500.','20 m² = 200 000 cm² ; 200 000 ÷ 2 500 = 80 cm².']}],
  ['Je repère le rapport k.','Longueurs × k, aires × k², volumes × k³.','Pour une translation, je déplace chaque point de la même façon.','Je vérifie : une translation ne change ni taille ni orientation.'],
  ['Multiplier les aires par k au lieu de k².','Confondre translation et rotation : une translation ne fait pas tourner.','Prendre un rapport supérieur à 1 pour une réduction.'],
  ['Rapport k : longueurs × k, aires × k², volumes × k³.','k &gt; 1 : agrandissement ; 0 &lt; k &lt; 1 : réduction.','Translation : glissement, tout est conservé.']),
 g:mix([d=>{const what=P(d===1?['longueur','aire']:['longueur','aire','volume']);const k=P(what==='volume'?[2,3,0.5]:d===1?[2,3,0.5]:[2,3,4,0.5,1.5,0.25]);const base=what==='volume'&&k===0.5?8*R(1,4):what==='aire'&&k===0.25?16*R(1,3):R(2,12);const f=what==='longueur'?k:what==='aire'?k*k:k**3;const unit=what==='longueur'?'cm':what==='aire'?'cm²':'cm³';
   return num(`On ${k>1?'agrandit':'réduit'} une figure avec le rapport ${nf(k)}. ${what==='volume'?'Un':'Une'} ${what} de ${base} ${unit} devient…`,Math.round(base*f*10000)/10000,{unit,expl:`${what==='longueur'?'× k':what==='aire'?'× k²':'× k³'} = × ${nf(f)} : ${base} × ${nf(f)} = <b>${nf(Math.round(base*f*10000)/10000)} ${unit}</b>.`,hint:'Longueur × k, aire × k², volume × k³.'});},3],
  [d=>{const x=R(-4,4),y=R(-4,4),a=R(-3,4)||2,b=R(-3,3);return ch(`Une translation déplace chaque point de ${Math.abs(a)} carreau${Math.abs(a)>1?'x':''} vers la ${a>0?'droite':'gauche'}${b?` et de ${Math.abs(b)} vers le ${b>0?'haut':'bas'}`:''}. Image du point A(${nf(x)} ; ${nf(y)}) ?`,`(${nf(x+a)} ; ${nf(y+b)})`,[`(${nf(x-a)} ; ${nf(y-b)})`,`(${nf(x+b)} ; ${nf(y+a)})`,`(${nf(x+a)} ; ${nf(y)})`].filter(z=>z!==`(${nf(x+a)} ; ${nf(y+b)})`).concat([`(${nf(x+a+1)} ; ${nf(y+b)})`]),{expl:`On ajoute ${nf(a)} à l’abscisse et ${nf(b)} à l’ordonnée : <b>(${nf(x+a)} ; ${nf(y+b)})</b>.`,hint:'Droite/gauche change l’abscisse, haut/bas l’ordonnée.'});},2],
  [d=>{const e=P([25,50,100,200]),m=R(2,9);return num(`Sur un plan à l’échelle 1/${e}, une pièce mesure ${m} cm de long. Longueur réelle en mètres ?`,m*e/100,{unit:'m',expl:`${m} × ${e} = ${m*e} cm = <b>${nf(m*e/100)} m</b>.`,hint:'Multiplie par le dénominateur de l’échelle.'});},2],
  [bank([['Une translation conserve…','les longueurs, les angles et les aires',['seulement les angles','seulement les longueurs','rien'],'L’image est superposable.'],['Un agrandissement de rapport 2 multiplie les aires par…','4',['2','8','6'],'k² = 4.'],{tf:'Une réduction de rapport 0,5 divise les volumes par 8.',v:true,e:'0,5³ = 0,125 = 1/8.',d:3}]),1])},

/* ======================= 4o ======================= */
{id:'4o',name:'Pyramides, cônes et volumes',icon:'🔺',domain:'Grandeurs et mesures',
 refs:[REF,REP+' : « calculer le volume d’une pyramide et d’un cône de révolution ; conversions d’unités de volume »'],
 tip:'Pyramide et cône : V = (aire de la base × hauteur) ÷ 3. Le « ÷ 3 » est la seule différence avec le prisme et le cylindre de même base et même hauteur.',
 c:C(`La pyramide du Louvre, un cornet de glace, un entonnoir… Comment calculer leur volume ? Une expérience simple le montre : il faut <b>trois</b> cônes remplis d’eau pour remplir le cylindre de même base et de même hauteur.`,
  [T('Les formules',`<p><b>Pyramide</b> : V = (B × h) ÷ 3, où B est l’aire de la base et h la hauteur (distance du sommet au plan de la base).</p><p><b>Cône de révolution</b> : la base est un disque de rayon r : V = (π × r² × h) ÷ 3.</p><p>Rappels : prisme et cylindre : V = B × h ; pavé : L × l × h.</p>`),
   T('Unités de volume',`<p>1 m³ = 1 000 dm³ ; 1 dm³ = 1 000 cm³ ; <b>1 dm³ = 1 L</b> ; 1 cm³ = 1 mL.</p><p>Exemple : une pyramide à base carrée de 6 cm de côté et de hauteur 10 cm : B = 36 cm², V = 36 × 10 ÷ 3 = <b>120 cm³</b> = 0,12 L.</p>`)],
  [{q:'Un cône a un rayon de 3 cm et une hauteur de 8 cm. Volume arrondi au cm³ ?',s:['Aire de la base : π × 3² = 9π cm².','V = 9π × 8 ÷ 3 = 24π cm³.','24π ≈ 75,4 donc V ≈ 75 cm³.']}],
  ['Je calcule l’aire de la base (carré, rectangle, triangle, disque).','Je multiplie par la hauteur.','Je divise par 3 pour une pyramide ou un cône.','Je convertis si besoin (1 L = 1 dm³).'],
  ['Oublier de diviser par 3.','Utiliser le diamètre à la place du rayon.','Prendre la longueur d’une arête latérale au lieu de la hauteur.'],
  ['Pyramide, cône : V = B × h ÷ 3.','Disque : aire π × r².','1 dm³ = 1 L ; 1 cm³ = 1 mL.']),
 g:mix([d=>{const c=R(2,12),h=3*R(1,6);return num(`Une pyramide a une base carrée de ${c} cm de côté et une hauteur de ${h} cm. Volume en cm³ ?`,c*c*h/3,{unit:'cm³',expl:`B = ${c}² = ${c*c} cm² ; V = ${c*c} × ${h} ÷ 3 = <b>${c*c*h/3} cm³</b>.`,hint:'B × h ÷ 3.'});},3],
  [d=>{const L=R(2,10),l=R(2,10),h=3*R(1,5);return num(`Une pyramide a une base rectangulaire de ${L} cm × ${l} cm et une hauteur de ${h} cm. Volume ?`,L*l*h/3,{unit:'cm³',expl:`B = ${L*l} cm² ; V = ${L*l} × ${h} ÷ 3 = <b>${L*l*h/3} cm³</b>.`,hint:'Aire du rectangle × hauteur ÷ 3.'});},2],
  [d=>{const r=R(1,8),h=R(2,15);const v=Math.round(Math.PI*r*r*h/3);return num(`Un cône a un rayon de ${r} cm et une hauteur de ${h} cm. Volume arrondi au cm³ ?`,v,{unit:'cm³',expl:`V = π × ${r}² × ${h} ÷ 3 = ${(r*r*h)%3?r*r*h+'π/3':nf(r*r*h/3)+'π'} ≈ <b>${v} cm³</b>.`,hint:'π r² h ÷ 3.'});},2],
  [d=>{const v=P([[2500,'cm³','L',2.5],[1500,'mL','L',1.5],[3,'dm³','L',3],[0.5,'m³','L',500],[750,'cm³','L',0.75],[2,'L','cm³',2000]]);return num(`Convertis ${nf(v[0])} ${v[1]} en ${v[2]}.`,v[3],{unit:v[2],expl:`1 L = 1 dm³ = 1 000 cm³ = 1 000 mL ; 1 m³ = 1 000 L. Résultat : <b>${nf(v[3])} ${v[2]}</b>.`,hint:'1 L = 1 dm³.'});},1],
  [bank([['Il faut combien de cônes pleins pour remplir le cylindre de même base et même hauteur ?','3',['2','4','π'],'V(cône) = V(cylindre) ÷ 3.'],{tf:'Le volume d’une pyramide se calcule comme celui d’un prisme.',v:false,e:'Il faut diviser par 3.'}]),1])},

/* ======================= 4p ======================= */
{id:'4p',name:'Théorème de Pythagore et réciproque',icon:'📐',domain:'Espace et géométrie',
 refs:[REF,REP+' : « utiliser le théorème de Pythagore pour calculer une longueur ; utiliser sa réciproque pour démontrer qu’un triangle est rectangle »'],
 tip:'L’hypoténuse est toujours en face de l’angle droit et c’est le plus long côté : c’est elle qui est seule de son côté du signe « = ».',
 c:C(`Les bâtisseurs égyptiens utilisaient une corde à 13 nœuds pour obtenir un angle droit : un triangle de côtés 3, 4 et 5 est rectangle. C’est un cas particulier du <b>théorème de Pythagore</b>.`,
  [T('Le théorème',`<p>Si un triangle ABC est <b>rectangle en A</b>, alors <b>BC² = AB² + AC²</b> ([BC] est l’hypoténuse).</p><p>Calculer l’hypoténuse : AB = 6, AC = 8 → BC² = 36 + 64 = 100, BC = 10.</p><p>Calculer un côté de l’angle droit : BC = 13, AB = 5 → AC² = 169 − 25 = 144, AC = 12.</p>`),
   T('La réciproque',`<p>Si dans un triangle ABC, <b>BC² = AB² + AC²</b> (BC étant le plus grand côté), alors le triangle est <b>rectangle en A</b>.</p><p>Si l’égalité n’est pas vérifiée, le triangle n’est pas rectangle (conséquence du théorème).</p><p>Rédaction : « Dans le triangle ABC, [BC] est le plus grand côté. BC² = … et AB² + AC² = … Donc… ».</p>`)],
  [{q:'Le triangle de côtés 7 cm, 24 cm et 25 cm est-il rectangle ?',s:['Le plus grand côté mesure 25 cm : 25² = 625.','7² + 24² = 49 + 576 = 625.','Égalité vérifiée : d’après la réciproque du théorème de Pythagore, le triangle est rectangle.']}],
  ['Je repère l’angle droit et l’hypoténuse.','J’écris l’égalité de Pythagore avec les noms des points.','Je remplace par les valeurs et je calcule.','Je conclus avec √ et l’unité (ou par « rectangle / non rectangle »).'],
  ['Additionner les longueurs au lieu de leurs carrés.','Se tromper d’hypoténuse.','Oublier de prendre la racine carrée à la fin.'],
  ['Rectangle en A ⇒ BC² = AB² + AC².','BC² = AB² + AC² ⇒ rectangle en A (réciproque).','L’hypoténuse est le plus grand côté.']),
 g:mix([d=>{const t=P([[3,4,5],[6,8,10],[5,12,13],[8,15,17],[9,12,15],[7,24,25],[12,16,20]]);return num(`ABC est rectangle en A, AB = ${t[0]} cm et AC = ${t[1]} cm. Calcule BC.`,t[2],{unit:'cm',expl:`BC² = ${t[0]}² + ${t[1]}² = ${t[0]**2} + ${t[1]**2} = ${t[2]**2} ; BC = <b>${t[2]} cm</b>.`,hint:'BC² = AB² + AC².'});},3],
  [d=>{const t=P([[3,4,5],[6,8,10],[5,12,13],[8,15,17],[9,40,41],[20,21,29]]);return num(`ABC est rectangle en A, BC = ${t[2]} cm et AB = ${t[0]} cm. Calcule AC.`,t[1],{unit:'cm',expl:`AC² = ${t[2]}² − ${t[0]}² = ${t[2]**2} − ${t[0]**2} = ${t[1]**2} ; AC = <b>${t[1]} cm</b>.`,hint:'AC² = BC² − AB².'});},2],
  [d=>{const a=R(2,12),b=R(2,12);const c=Math.round(Math.sqrt(a*a+b*b)*10)/10;return num(`ABC est rectangle en A, AB = ${a} cm et AC = ${b} cm. Calcule BC arrondi au dixième.`,c,{unit:'cm',tol:0.0501,expl:`BC² = ${a*a} + ${b*b} = ${a*a+b*b} ; BC = √${a*a+b*b} ≈ <b>${nf(c)} cm</b>.`,hint:'N’oublie pas la racine carrée.'});},2],
  [d=>{const t=P([[3,4,5],[5,12,13],[6,8,10],[8,15,17],[4,5,6],[5,6,8],[6,7,9],[10,24,26],[7,9,11]]);const ok=t[0]**2+t[1]**2===t[2]**2;return ch(`Un triangle a pour côtés ${t[0]} cm, ${t[1]} cm et ${t[2]} cm. Est-il rectangle ?`,ok?'Oui':'Non',[ok?'Non':'Oui'],{expl:`${t[2]}² = ${t[2]**2} ; ${t[0]}² + ${t[1]}² = ${t[0]**2+t[1]**2}. ${ok?'Égalité : il est rectangle (réciproque).':'Pas d’égalité : il n’est pas rectangle.'}`,hint:'Compare le carré du plus grand côté et la somme des deux autres carrés.'});},2],
  [bank([['Dans le triangle DEF rectangle en E, l’hypoténuse est…','[DF]',['[DE]','[EF]','le côté le plus court'],'En face de l’angle droit E.'],['Une télé de 80 cm de large et 60 cm de haut a une diagonale de…','100 cm',['140 cm','120 cm','70 cm'],'√(80² + 60²) = √10 000 = 100.',2]]),1])},

/* ======================= 4q ======================= */
{id:'4q',name:'Thalès et triangles emboîtés',icon:'🔻',domain:'Espace et géométrie',
 refs:[REF,REP+' : « utiliser le théorème de Thalès dans la configuration des triangles emboîtés ; agrandissement-réduction »'],
 tip:'Petit triangle sur grand triangle, dans le même ordre : AM/AB = AN/AC = MN/BC. Mets le sommet commun A en premier partout.',
 c:C(`Dans le triangle ABC, on trace une parallèle à (BC) qui coupe [AB] en M et [AC] en N. Le petit triangle AMN est une <b>réduction</b> du grand triangle ABC : ses côtés sont proportionnels. C’est le <b>théorème de Thalès</b>.`,
  [T('Énoncé (triangles emboîtés)',`<p>Si M ∈ [AB], N ∈ [AC] et (MN) // (BC), alors <b>AM/AB = AN/AC = MN/BC</b>.</p><p>Le triangle AMN est une réduction de ABC de rapport k = AM/AB.</p>`),
   T('Calculer une longueur',`<p>AM = 2, AB = 6, BC = 9 : AM/AB = MN/BC donne 2/6 = MN/9, donc MN = 9 × 2 ÷ 6 = <b>3</b>.</p><p>On utilise l’égalité de deux rapports et le produit en croix. Il faut toujours vérifier d’abord le parallélisme (hypothèse).</p>`)],
  [{q:'(MN) // (BC), AM = 3 cm, AB = 7,5 cm, AN = 4 cm. Calculer AC.',s:['D’après le théorème de Thalès : AM/AB = AN/AC.','3/7,5 = 4/AC.','AC = 7,5 × 4 ÷ 3 = 10 cm.']}],
  ['Je vérifie que les droites sont parallèles et que les points sont alignés.','J’écris les trois rapports avec A en premier.','Je choisis les deux rapports utiles.','Je calcule par produit en croix et je conclus.'],
  ['Écrire AM/MB au lieu de AM/AB.','Appliquer Thalès sans droites parallèles.','Inverser petit et grand triangle dans un des rapports.'],
  ['(MN) // (BC) ⇒ AM/AB = AN/AC = MN/BC.','Le petit triangle est une réduction du grand.','Produit en croix pour trouver la longueur.']),
 g:mix([d=>{const ab=R(4,12),am=R(1,ab-1),k=R(2,5);return num(`M ∈ [AB], N ∈ [AC] et (MN) // (BC). AM = ${am} cm, AB = ${ab} cm, BC = ${ab*k} cm. Calcule MN.`,am*k,{unit:'cm',expl:`AM/AB = MN/BC ⇒ MN = ${ab*k} × ${am} ÷ ${ab} = <b>${am*k} cm</b>.`,hint:'MN/BC = AM/AB.'});},3],
  [d=>{const am=R(2,6),k=P([2,3,1.5,2.5]),an=R(2,7);return num(`M ∈ [AB], N ∈ [AC] et (MN) // (BC). AM = ${am} cm, AB = ${nf(am*k)} cm, AN = ${an} cm. Calcule AC.`,an*k,{unit:'cm',expl:`AM/AB = AN/AC ⇒ AC = ${an} × ${nf(am*k)} ÷ ${am} = <b>${nf(an*k)} cm</b>.`,hint:'Écris AM/AB = AN/AC.'});},3],
  [d=>{const k=P([2,3,4]),mn=R(2,8);return num(`AMN est une réduction de ABC de rapport 1/${k}. MN = ${mn} cm. Combien mesure BC ?`,mn*k,{unit:'cm',expl:`BC = MN × ${k} = <b>${mn*k} cm</b>.`,hint:`Le grand triangle a des côtés ${k} fois plus longs.`});},2],
  [bank([['Quelle hypothèse est indispensable pour appliquer le théorème de Thalès ?','(MN) parallèle à (BC)',['ABC rectangle','AM = MB','ABC isocèle'],'Le parallélisme est l’hypothèse clé.'],{tf:'Si (MN) // (BC), alors AM/AB = MN/BC.',v:true,e:'C’est le théorème de Thalès.'}]),1])},

/* ======================= 4r ======================= */
{id:'4r',name:'Cosinus dans le triangle rectangle',icon:'📏',domain:'Espace et géométrie',
 refs:[REF,REP+' : « utiliser le cosinus d’un angle aigu dans un triangle rectangle pour calculer une longueur ou un angle »'],
 tip:'cos = côté ADJACENT ÷ HYPOTÉNUSE. Le côté adjacent touche l’angle et n’est pas l’hypoténuse.',
 c:C(`Une rampe d’accès de 5 m fait un angle de 6° avec le sol : quelle longueur au sol occupe-t-elle ? Dans un triangle rectangle, le <b>cosinus</b> d’un angle aigu relie cet angle à deux côtés.`,
  [T('Définition',`<p>Dans un triangle ABC rectangle en A, pour l’angle aigu B : <b>cos B = AB/BC = côté adjacent/hypoténuse</b>.</p><p>Le cosinus d’un angle aigu est toujours compris entre 0 et 1. cos 60° = 0,5 ; cos 0° = 1.</p>`),
   T('Utiliser le cosinus',`<p><b>Longueur adjacente</b> : AB = BC × cos B. Rampe : 5 × cos 6° ≈ 4,97 m.</p><p><b>Hypoténuse</b> : BC = AB ÷ cos B.</p><p><b>Angle</b> : cos B = AB/BC puis touche « cos⁻¹ » (ou « Arccos ») de la calculatrice en mode degrés : si AB = 4 et BC = 8, cos B = 0,5 et B = 60°.</p>`)],
  [{q:'ABC rectangle en A, BC = 10 cm, angle B = 40°. Calculer AB au dixième.',s:['AB est adjacent à B, BC est l’hypoténuse.','cos 40° = AB/10.','AB = 10 × cos 40° ≈ 7,7 cm.']}],
  ['Je vérifie que le triangle est rectangle.','Je repère l’hypoténuse et le côté adjacent à l’angle.','J’écris cos(angle) = adjacent/hypoténuse.','Je calcule (calculatrice en degrés) et j’arrondis à la fin.'],
  ['Prendre le côté opposé au lieu du côté adjacent.','Utiliser le cosinus dans un triangle non rectangle.','Calculatrice en radians.'],
  ['cos = adjacent/hypoténuse.','Adjacent = hypoténuse × cos ; hypoténuse = adjacent ÷ cos.','Angle : cos⁻¹.']),
 g:mix([d=>{const ang=P([20,25,30,35,40,45,50,55,60,65,70]),hyp=R(4,20);const v=Math.round(hyp*Math.cos(ang*Math.PI/180)*10)/10;return num(`ABC est rectangle en A, BC = ${hyp} cm et l’angle B mesure ${ang}°. Calcule AB arrondi au dixième.`,v,{unit:'cm',tol:0.0501,expl:`cos ${ang}° = AB/${hyp} ⇒ AB = ${hyp} × cos ${ang}° ≈ <b>${nf(v)} cm</b>.`,hint:'Adjacent = hypoténuse × cos.'});},3],
  [d=>{const ang=P([25,30,35,40,50,60]),adj=R(3,12);const v=Math.round(adj/Math.cos(ang*Math.PI/180)*10)/10;return num(`ABC est rectangle en A, AB = ${adj} cm et l’angle B mesure ${ang}°. Calcule l’hypoténuse BC arrondie au dixième.`,v,{unit:'cm',tol:0.0501,expl:`cos ${ang}° = ${adj}/BC ⇒ BC = ${adj} ÷ cos ${ang}° ≈ <b>${nf(v)} cm</b>.`,hint:'Hypoténuse = adjacent ÷ cos.'});},2],
  [d=>{const t=P([[4,8,60],[5,10,60],[3,6,60],[7,14,60]]);return num(`ABC est rectangle en A, AB = ${t[0]} cm et BC = ${t[1]} cm. Mesure de l’angle B ?`,t[2],{unit:'°',expl:`cos B = ${t[0]}/${t[1]} = 0,5 ⇒ B = <b>60°</b>.`,hint:'cos⁻¹(0,5).'});},1],
  [d=>{const hyp=R(5,15),ang=P([25,35,40,50,55,65]);const adj=Math.round(hyp*Math.cos(ang*Math.PI/180)*10)/10;const a=Math.round(Math.acos(adj/hyp)*180/Math.PI);return num(`ABC est rectangle en A, AB = ${nf(adj)} cm et BC = ${hyp} cm. Mesure de l’angle B arrondie au degré ?`,a,{unit:'°',tol:0.5,expl:`cos B = ${nf(adj)}/${hyp} ≈ ${dec(adj/hyp,4)} ⇒ B ≈ <b>${a}°</b>.`,hint:'cos⁻¹ de la calculatrice.'});},2],
  [bank([['Dans ABC rectangle en A, le cosinus de l’angle C est égal à…','AC/BC',['AB/BC','AC/AB','BC/AC'],'Côté adjacent à C : [AC] ; hypoténuse : [BC].'],{tf:'Le cosinus d’un angle aigu peut valoir 1,5.',v:false,e:'Le côté adjacent est plus court que l’hypoténuse : cos &lt; 1.'}]),1])},

/* ======================= 4s ======================= */
{id:'4s',name:'Raisonner et démontrer en géométrie',icon:'🧠',domain:'Espace et géométrie',
 refs:[REF,REP+' : « mener des raisonnements et s’initier à la démonstration ; utiliser les propriétés des angles et des figures usuelles »'],
 tip:'Une démonstration en trois temps : « On sait que… (données) », « Or… (propriété) », « Donc… (conclusion) ».',
 c:C(`En géométrie, on ne peut pas se fier à une figure ni à une mesure au rapporteur : il faut <b>démontrer</b>, c’est-à-dire déduire une conclusion de données sûres à l’aide de propriétés connues.`,
  [T('Propriétés d’angles',`<p>La somme des angles d’un triangle vaut <b>180°</b>.</p><p>Deux angles <b>opposés par le sommet</b> sont égaux. Si deux droites parallèles sont coupées par une sécante, les angles <b>alternes-internes</b> sont égaux et les angles <b>correspondants</b> sont égaux ; réciproquement, si des angles alternes-internes (ou correspondants) sont égaux, les droites sont parallèles.</p><p>Dans un triangle isocèle, les angles à la base sont égaux ; dans un triangle équilatéral, chaque angle mesure 60°.</p>`),
   T('Démontrer',`<p>Exemple : ABC a des angles A = 50° et B = 65°. On sait que la somme des angles d’un triangle vaut 180°, donc C = 180° − 50° − 65° = 65°. Les angles B et C étant égaux, le triangle est isocèle en A.</p><p>Propriétés de quadrilatères : un parallélogramme a ses côtés opposés parallèles et de même longueur, ses diagonales se coupent en leur milieu ; un rectangle a ses diagonales de même longueur ; un losange a ses diagonales perpendiculaires.</p>`)],
  [{q:'(d) // (d′), une sécante forme avec (d) un angle de 72°. Que vaut l’angle alterne-interne correspondant avec (d′) ?',s:['On sait que (d) et (d′) sont parallèles.','Or si deux droites parallèles sont coupées par une sécante, les angles alternes-internes sont égaux.','Donc l’angle mesure 72°.']}],
  ['J’écris les données (« On sait que… »).','Je cite la propriété utilisée (« Or… »).','Je conclus (« Donc… »).','Je ne m’appuie jamais sur une mesure faite sur la figure.'],
  ['Utiliser une mesure faite au rapporteur comme preuve.','Citer la réciproque à la place du théorème (ou l’inverse).','Conclure sans citer la propriété.'],
  ['Somme des angles d’un triangle : 180°.','Parallèles + sécante ⇒ angles alternes-internes égaux (et réciproque).','On sait que… Or… Donc…']),
 g:mix([d=>{const a=R(20,100),b=R(20,150-a);return num(`Dans un triangle, deux angles mesurent ${a}° et ${b}°. Combien mesure le troisième ?`,180-a-b,{unit:'°',expl:`180 − ${a} − ${b} = <b>${180-a-b}°</b> (somme des angles d’un triangle).`,hint:'La somme vaut 180°.'});},3],
  [d=>{const a=R(30,80);const t=P(['base','sommet']);return t==='base'?num(`Un triangle isocèle a un angle au sommet principal de ${2*(90-a)}°. Combien mesure chacun des angles à la base ?`,a,{unit:'°',expl:`(180 − ${2*(90-a)}) ÷ 2 = <b>${a}°</b>.`,hint:'Les deux angles à la base sont égaux.'}):num(`Un triangle isocèle a deux angles à la base de ${a}°. Combien mesure l’angle au sommet principal ?`,180-2*a,{unit:'°',expl:`180 − 2 × ${a} = <b>${180-2*a}°</b>.`,hint:'Somme des angles : 180°.'});},2],
  [d=>{const a=R(25,155);const k=P(['alternes-internes','correspondants','opposés par le sommet']);return num(`Deux droites parallèles sont coupées par une sécante. Un angle mesure ${a}°. Combien mesure l’angle qui lui est ${k==='opposés par le sommet'?'opposé par le sommet':k.replace(/s$/,'').replace('alternes-internes','alterne-interne').replace('correspondants','correspondant')} ?`,a,{unit:'°',expl:`Les angles ${k} sont égaux : <b>${a}°</b>.`,hint:'Ces angles ont la même mesure.'});},2],
  [d=>{const props=[['Un quadrilatère dont les diagonales se coupent en leur milieu est…','un parallélogramme',['un trapèze','un cerf-volant','un triangle']],['Un parallélogramme dont les diagonales ont la même longueur est…','un rectangle',['un losange','un trapèze','un cerf-volant']],['Un parallélogramme dont les diagonales sont perpendiculaires est…','un losange',['un rectangle','un trapèze','un triangle']],['Un triangle dont les trois angles mesurent 60° est…','équilatéral',['rectangle','isocèle non équilatéral','quelconque']]];const p=P(props);return ch(p[0],p[1],p[2],{expl:`Propriété du cours : ${p[0].replace('…','')} ${p[1]}.`,hint:'Pense aux propriétés des diagonales.'});},2],
  [bank([['Pourquoi ne peut-on pas « démontrer » avec un rapporteur ?','une mesure est approximative et ne prouve rien en général',['le rapporteur est interdit','les angles ne se mesurent pas','c’est trop long'],'Une démonstration s’appuie sur des propriétés.'],['Les angles d’un triangle mesurent 90°, 30° et… ?','60°',['90°','70°','180°'],'180 − 90 − 30 = 60.'],{tf:'Si deux angles alternes-internes sont égaux, les droites sont parallèles.',v:true,e:'C’est la réciproque de la propriété des angles alternes-internes.',d:2}]),1])},

/* ======================= 4t ======================= */
{id:'4t',name:'Algorithmique : variables, conditions et boucles',icon:'🤖',domain:'Algorithmique et programmation',
 refs:[REF,REP+' : « écrire et exécuter un programme avec variables, boucles et instructions conditionnelles »'],
 tip:'Exécute le programme à la main avec un tableau : une colonne par variable, une ligne par instruction.',
 c:C(`Dans Scratch, un lutin peut dessiner, compter des points ou réagir à une touche. Ce qu’il fait dépend des <b>variables</b>, des <b>boucles</b> et des <b>conditions</b> du programme.`,
  [T('Variables et boucles',`<p>Une variable stocke une valeur : « mettre score à 0 », puis « ajouter 5 à score ».</p><p>« Répéter 10 fois » exécute un bloc 10 fois ; « répéter indéfiniment » ne s’arrête jamais ; « répéter jusqu’à » s’arrête quand la condition devient vraie.</p>`),
   T('Conditions',`<p>« si … alors … » : le bloc n’est exécuté que si la condition est vraie. « si … alors … sinon … » choisit entre deux blocs.</p><p>Exemple : si score &gt; 100 alors dire « Gagné ! » sinon dire « Encore ! ».</p><p>Tracer un carré : « répéter 4 fois : avancer de 100 ; tourner de 90° ».</p>`)],
  [{q:'score ← 0 ; répéter 5 fois : ajouter 3 à score. Valeur finale de score ?',s:['Au départ score = 0.','Chaque tour ajoute 3.','Après 5 tours : 0 + 5 × 3 = 15.']}],
  ['Je note la valeur initiale des variables.','J’exécute les instructions une par une.','Je compte les tours de boucle.','Je teste les conditions avec les valeurs du moment.'],
  ['Oublier la valeur initiale d’une variable.','Compter un tour de trop dans une boucle.','Exécuter les deux branches d’un « si … sinon ».'],
  ['Variable = « boîte » contenant une valeur.','Boucles : répéter n fois, répéter jusqu’à, indéfiniment.','Condition : une seule branche exécutée.']),
 g:mix([d=>{const x0=R(0,9),n=R(2,d===1?4:7),k=R(2,8);const op=P(['+','×2']);let x=x0;for(let i=0;i<n;i++)x=op==='+'?x+k:x*2;return num(`x ← ${x0} ; répéter ${n} fois : ${op==='+'?`x ← x + ${k}`:'x ← x × 2'}. Valeur finale de x ?`,x,{expl:`${n} tours depuis ${x0} : <b>${x}</b>.`,hint:'Tableau tour par tour.'});},3],
  [d=>{const x=R(0,30),s=R(10,20),a=R(1,9),b=R(1,9);const r=x>=s?x-a:x+b;return num(`Si x ≥ ${s} alors x ← x − ${a} sinon x ← x + ${b}. Avec x = ${x}, que vaut x à la fin ?`,r,{expl:`${x} ${x>=s?'≥':'&lt;'} ${s} : branche « ${x>=s?'alors':'sinon'} » → <b>${r}</b>.`,hint:'Teste la condition d’abord.'});},2],
  [d=>{const n=P([3,4,5,6,8]);return num(`Pour tracer un polygone régulier à ${n} côtés : « répéter ${n} fois : avancer de 50 ; tourner de … ° ». Quel angle ?`,360/n,{unit:'°',expl:`360 ÷ ${n} = <b>${360/n}°</b>.`,hint:'Un tour complet = 360°.'});},2],
  [d=>{const lim=P([20,30,50,100]),step=P([3,4,5,7]);let x=0,c=0;while(x<lim&&c<60){x+=step;c++;}return num(`x ← 0 ; compteur ← 0 ; répéter jusqu’à x ≥ ${lim} : x ← x + ${step} ; compteur ← compteur + 1. Valeur finale du compteur ?`,c,{expl:`x atteint ${x} ≥ ${lim} après <b>${c}</b> tours.`,hint:'Compte les ajouts jusqu’à dépasser la limite.'});},2],
  [bank([['Quelle boucle ne s’arrête jamais ?','répéter indéfiniment',['répéter 10 fois','répéter jusqu’à x = 5','si … alors'],'Elle tourne sans fin.'],['Dans « si … alors … sinon … », combien de blocs sont exécutés ?','un seul',['les deux','aucun','trois'],'Si la condition est vraie, on exécute le bloc « alors », sinon le bloc « sinon » : jamais les deux.']]),1])}
]);
})();
